import{n as l}from"./shared-CAKwAg2C.js";const p={"LEARN HOW THE INTERNET WORKS":"ЯК ПРАЦЮЄ ІНТЕРНЕТ","NOW LEARNING":"ЗАРАЗ ВИВЧАЄТЕ","OSI LAYER":"РІВЕНЬ OSI","LEARNING PROGRESS":"ПРОГРЕС НАВЧАННЯ",COMPLETE:"ЗАВЕРШЕНО","IN PROGRESS":"У ПРОЦЕСІ","{pct}% complete":"Завершено {pct}%","DESIGNED BY":"ДИЗАЙН","Dilum Sanjaya on X":"Dilum Sanjaya в X","Layer {n}: {name}":"Рівень {n}: {name}",Physical:"Фізичний","Data Link":"Канальний",Network:"Мережевий",Transport:"Транспортний",Session:"Сеансовий",Presentation:"Представлення",Application:"Прикладний","OVERVIEW · {n} STEPS":"ОГЛЯД · {n} КРОКІВ","STEP {n}/{total} · {title}":"КРОК {n}/{total} · {title}","LESSON COMPLETE":"УРОК ЗАВЕРШЕНО",PROTOCOLS:"ПРОТОКОЛИ",Protocols:"Протоколи",Language:"Мова",Theme:"Тема","Light mode":"Світла тема","Dark mode":"Темна тема","INTERNET PROTOCOLS":"ІНТЕРНЕТ-ПРОТОКОЛИ",More:"Більше","Close the protocol list":"Закрити список протоколів","Close (Esc)":"Закрити (Esc)",ALL:"УСІ",CORE:"ОСНОВНІ",APPLICATION:"ПРИКЛАДНІ",SECURITY:"БЕЗПЕКА",NETWORK:"МЕРЕЖА",SEQUENCE:"ПОСЛІДОВНІСТЬ",View:"Вигляд","Switch view (V)":"Змінити вигляд (V)","Network diagram":"Схема мережі","Sequence diagram":"Діаграма послідовності","STEP {n}":"КРОК {n}","PROTOCOL OVERVIEW":"ОГЛЯД ПРОТОКОЛУ","STEP DETAILS":"ДЕТАЛІ КРОКУ","LESSON SUMMARY":"ПІДСУМОК УРОКУ",OVERVIEW:"ОГЛЯД",ACTIVE:"АКТИВНИЙ","STEP {n} OF {total}":"КРОК {n}/{total}","PACKET {n} OF {total}":"ПАКЕТ {n}/{total}","PACKETS {from}–{to} OF {total}":"ПАКЕТИ {from}–{to}/{total}","{n} LOST":"ВТРАЧЕНО: {n}","1 LOST":"ВТРАЧЕНО: 1",ENCRYPTED:"ЗАШИФРОВАНО","LOST ON THE WAY":"ВТРАЧЕНО ДОРОГОЮ","PACKET FLOW":"ПОТІК ПАКЕТІВ","Colour key":"Легенда кольорів","Playback speed":"Швидкість відтворення","Previous step (←)":"Попередній крок (←)","Previous step":"Попередній крок","Play / pause (Space)":"Відтворити / пауза (Пробіл)",PLAY:"ПУСК",PAUSE:"ПАУЗА",REPLAY:"ЗНОВУ",STEP:"КРОК","One packet at a time":"По одному пакету",RESET:"СКИНУТИ",Reset:"Скинути","Back to the overview (Esc)":"Назад до огляду (Esc)","NO.":"№",TIME:"ЧАС",SOURCE:"ДЖЕРЕЛО",DESTINATION:"ПРИЗНАЧЕННЯ",PROTOCOL:"ПРОТОКОЛ",INFO:"ІНФО",SIZE:"РОЗМІР","No packets on the wire yet.":"На лінії ще немає пакетів.",LOST:"ВТРАЧЕНО","Packet inspector":"Інспектор пакетів","Previous packet":"Попередній пакет","Previous packet (←)":"Попередній пакет (←)","Next packet":"Наступний пакет","Next packet (→)":"Наступний пакет (→)",Close:"Закрити","E.G.":"НАПР.","an example value: it differs in every real capture":"приклад значення: у кожному справжньому захопленні воно інше","bytes the lesson can’t show: encrypted, random, or a file’s contents":"байти, яких урок не може показати: зашифровані, випадкові або вміст файлу",BYTES:"БАЙТИ","{n} in this frame":"{n} у цьому кадрі","This row stands for {n} TCP segments carrying a {size}-byte message; the first segment is shown":"Цей рядок охоплює кілька TCP-сегментів ({n}), що несуть повідомлення обсягом {size} B; показано перший сегмент","This packet was lost on the way":"Цей пакет загубився дорогою",Padding:"Доповнення","192.168.1.10/24 · 24 H LEASE":"192.168.1.10/24 · НА 24 ГОД","2 SEGMENTS":"2 СЕГМЕНТИ","3 SEGMENTS":"3 СЕГМЕНТИ","3 DATAGRAMS":"3 ДАТАГРАМИ","4 DATAGRAMS":"4 ДАТАГРАМИ","203.0.113.10 IS NOT LOCAL":"203.0.113.10 НЕ В ЛОКАЛЬНІЙ МЕРЕЖІ","250 QUEUED":"250 У ЧЕРЗІ",ANSWER:"ВІДПОВІДЬ","APP COVERS THE 20 MS GAP":"ЗАСТОСУНОК ПРИХОВУЄ ПРОГАЛИНУ 20 MS","APP DATA":"ДАНІ ЗАСТОСУНКУ","ARP REPLY":"ARP-ВІДПОВІДЬ","ARP REQUEST":"ARP-ЗАПИТ","ARRIVED WITH TTL 116":"ПРИБУВ: TTL 116","AUTH FAILURE":"ВІДМОВА AUTH","At QUIT":"Під час QUIT","CACHED · TTL 3600 S":"У КЕШІ · TTL 3600 S","CERTIFICATE VALID":"СЕРТИФІКАТ ДІЙСНИЙ","CHAIN LEADS TO A TRUSTED ROOT":"ЛАНЦЮЖОК ВЕДЕ ДО ДОВІРЕНОГО КОРЕНЯ","CHANNEL OPEN":"ВІДКРИТТЯ КАНАЛУ",CONFIRMED:"ПІДТВЕРДЖЕНО","DNS QUERY":"DNS-ЗАПИТ","DNS REPLY":"DNS-ВІДПОВІДЬ","DUP ACK":"ДУБЛЬ ACK","EACH KEY IS ITS OWN PACKET":"КОЖНА КЛАВІША — ОКРЕМИЙ ПАКЕТ",ECHO:"ЕХО","ECHO REPLY":"ЕХО-ВІДПОВІДЬ","ECHO REQUEST":"ЕХО-ЗАПИТ",ENTER:"ENTER","FRAME 7 LOST · NOT RESENT":"КАДР 7 ВТРАЧЕНО · НЕ ПОВТОРЕНО","HOP 2 · 198.51.100.1":"ХОП 2 · 198.51.100.1","HOST KEY MATCHES KNOWN_HOSTS":"КЛЮЧ ХОСТА Є В KNOWN_HOSTS","IN BOB’S MAILBOX":"У СКРИНЬЦІ БОБА","IP PACKET":"IP-ПАКЕТ",MESSAGE:"ЛИСТ","MESSAGE 1 DELETED":"ЛИСТ 1 ВИДАЛЕНО","NEW MAIL ARRIVED":"НАДІЙШОВ НОВИЙ ЛИСТ","NO IP ADDRESS YET":"ЩЕ НЕМАЄ IP-АДРЕСИ","NOT IN CACHE":"НЕМАЄ В КЕШІ","OFFER KEY":"ПРОПОЗИЦІЯ КЛЮЧА",OUTPUT:"ВИВІД","PASSWORD IN PLAIN TEXT":"ПАРОЛЬ ВІДКРИТИМ ТЕКСТОМ",REFERRAL:"ПЕРЕНАПРАВЛЕННЯ",REPLY:"ВІДПОВІДЬ",RESEND:"ПОВТОР","SEGMENT 1 LOST":"СЕГМЕНТ 1 ВТРАЧЕНО","SFTP or FTPS":"SFTP або FTPS","SFTP, or FTPS (FTP + TLS)":"SFTP або FTPS (FTP + TLS)","SHARED SECRET COMPUTED":"СПІЛЬНИЙ СЕКРЕТ ОБЧИСЛЕНО",SIGNED:"ПІДПИСАНО","STILL ON SERVER · \\SEEN":"ДОСІ НА СЕРВЕРІ · \\SEEN",SUCCESS:"УСПІХ","TIME EXCEEDED":"ЧАС ВИЧЕРПАНО","TIME=34MS TTL=52":"TIME=34MS TTL=52",UNREACHABLE:"НЕДОСЯЖНО",VERSION:"ВЕРСІЯ","VOICE 1":"ГОЛОС 1","+OK or -ERR":"+OK або -ERR",".com Server":"Сервер .com",Authoritative:"Авторитетний","Log In":"Вхід",Key:"Ключ",Why:"Навіщо",End:"Кінець","MACs, in":"MAC, вхідні",Internet:"Інтернет",Router:"Маршрутизатор","Router 192.168.1.1":"Маршрутизатор 192.168.1.1","Router: 192.168.1.1":"Маршрутизатор: 192.168.1.1",Routers:"Маршрутизатори",Hardware:"Обладнання",Audio:"Аудіо",Ping:"Ping",Cookie:"Cookie","Magic cookie":"Magic cookie",Visible:"Що видно",Tickets:"Квитки","4, 20 bytes":"4, 20 байтів","20–60 bytes":"20–60 байтів","20–60 bytes (IPv4)":"20–60 байтів (IPv4)","8 bytes (TCP: 20+)":"8 байтів (TCP: 20+)","32 bytes (Windows)":"32 байти (Windows)","1,460 bytes (MSS)":"1,460 байтів (MSS)","78 bytes (seq 1–78)":"78 байтів (seq 1–78)","bytes 1461–2920":"байти 1461–2920","text/html, 12.2 KB":"text/html, 12.2 KB","1026 (× 256 = 262,656 bytes)":"1026 (× 256 = 262,656 байтів)","501 (× 128 = 64,128 bytes)":"501 (× 128 = 64,128 байтів)","X25519MLKEM768 (1,216 bytes), X25519":"X25519MLKEM768 (1,216 байтів), X25519","X25519MLKEM768 (1,120 bytes)":"X25519MLKEM768 (1,120 байтів)",'"abcdefghijklmnopqrstuvwabcdefghi" (32 bytes)':'"abcdefghijklmnopqrstuvwabcdefghi" (32 байти)','"hello, anyone here" (18 bytes)':'"hello, anyone here" (18 байтів)',"32 bits (IPv4), 128 (IPv6)":"32 біти (IPv4), 128 (IPv6)","64 → 52 (12 routers)":"64 → 52 (12 маршрутизаторів)","52 (64 − 12 routers)":"52 (64 − 12 маршрутизаторів)","1 (Ethernet)":"1 (Ethernet)","report.pdf, 4,000 bytes":"report.pdf, 4,000 байтів","1190 bytes (sntrup761 1,158 + X25519 32)":"1190 байтів (sntrup761 1,158 + X25519 32)","RTP + audio":"RTP + аудіо"},T={"Hypertext Transfer Protocol":"Передача гіпертексту","HTTP Secure":"Захищений HTTP","Transmission Control Protocol":"Керування передачею","User Datagram Protocol":"Датаграми користувача","Internet Protocol":"Інтернет-протокол","Domain Name System":"Система доменних імен","Dynamic Host Configuration":"Динамічне налаштування хостів","Internet Control Message":"Службові повідомлення мережі","Simple Mail Transfer Protocol":"Проста передача пошти","Post Office Protocol v3":"Post Office Protocol v3","Internet Message Access":"Доступ до поштових повідомлень","File Transfer Protocol":"Передача файлів","Secure Shell":"Захищена оболонка","Transport Layer Security":"Безпека транспортного рівня",Internet:"Інтернет",Client:"Клієнт",Router:"Маршрутизатор","DNS Resolver":"DNS-резолвер","Web Server":"Вебсервер","Root Server":"Кореневий сервер",".com TLD Server":"Сервер TLD .com","Authoritative Server":"Авторитетний сервер","Mail Server":"Поштовий сервер","Web Communication":"Вебкомунікація",Request:"Запит",Response:"Відповідь","Data ACKs not shown":"ACK на дані не показано","HTTP is the protocol of the web: a client asks for a resource, such as an HTML page, and the server answers with a status code, headers and usually a body. Every exchange is one request and one response, written as readable text in HTTP/1.1.":"HTTP — протокол вебу: клієнт запитує ресурс, наприклад HTML-сторінку, а сервер відповідає кодом стану, заголовками і зазвичай тілом. Кожен обмін складається з одного запиту й однієї відповіді, які в HTTP/1.1 записано читабельним текстом.",Layer:"Рівень","Application (Layer 7)":"Прикладний (рівень 7)","Default Port":"Стандартний порт",Transport:"Транспортний","Data Format":"Формат даних","Text (headers + optional body)":"Текст (заголовки + необов’язкове тіло)","Common Methods":"Поширені методи","Defined In":"Визначено в","Page delivered":"Сторінку доставлено","One request, one response":"Один запит, одна відповідь","In under a tenth of a second the laptop looked up an address, opened a TCP connection and exchanged one HTTP request and response, all of it readable by anyone on the path. Press REPLAY to watch it again.":"Менш ніж за десяту частку секунди ноутбук знайшов адресу, відкрив TCP-з’єднання та обмінявся одним HTTP-запитом і відповіддю, і все це міг прочитати будь-хто на шляху. Натисніть ЗНОВУ, щоб переглянути ще раз.","Round trips":"Обміни туди-назад","Total time":"Загальний час","Page size":"Розмір сторінки","Sent as 9 TCP segments":"Надіслано 9 TCP-сегментами","Client Request":"Запит клієнта","Browser prepares the request":"Браузер готує запит","You open http://www.example.com. The browser will send a GET request, but packets travel to IP addresses, not names, so first it needs the server’s address. (Browsers now try https:// first; this is the plain version.)":"Ви відкриваєте http://www.example.com. Браузер надішле запит GET, але пакети йдуть на IP-адреси, а не на імена, тож спершу йому потрібна адреса сервера. (Сьогодні браузери спершу пробують https://; тут показано незашифрований варіант.)",Method:"Метод","Next hop":"Наступний хоп","Router 192.168.1.1":"Маршрутизатор 192.168.1.1","DNS Resolution":"Розв’язання DNS","Finds the server’s IP address":"Знаходить IP-адресу сервера","The laptop asks the DNS server it was given by DHCP, 8.8.8.8, for the address of www.example.com. The query goes over UDP port 53 and the answer is an A record with the IPv4 address. (On a network with IPv6 it would also ask for an AAAA record.)":"Ноутбук запитує в DNS-сервера, якого отримав через DHCP, 8.8.8.8, адресу www.example.com. Запит іде через UDP-порт 53, а відповідь — це запис A з IPv4-адресою. (У мережі з IPv6 він також запитав би запис AAAA.)",Resolver:"Резолвер","8.8.8.8 (had it cached)":"8.8.8.8 (мав її в кеші)","UDP, port 53":"UDP, порт 53",Answer:"Відповідь","TCP Connection":"TCP-з’єднання","Establishes a reliable link":"Встановлює надійний зв’язок","HTTP runs on top of TCP. Before any page data moves, the laptop and the server open a connection to port 80 with a three-way handshake: SYN, SYN-ACK, ACK.":"HTTP працює поверх TCP. Перш ніж передати будь-які дані сторінки, ноутбук і сервер відкривають з’єднання з портом 80 через тристороннє рукостискання: SYN, SYN-ACK, ACK.","Server port":"Порт сервера","Client port":"Порт клієнта",Handshake:"Рукостискання","HTTP Exchange":"Обмін HTTP","Request and response messages":"Повідомлення запиту й відповіді","The browser sends a GET request with a Host header. The server answers 200 OK with the HTML in the body: 12.2 KB, too big for one packet, so TCP splits it into 9 segments of up to 1460 bytes (drawn here as one).":"Браузер надсилає запит GET із заголовком Host. Сервер відповідає 200 OK з HTML у тілі: 12.2 KB, забагато для одного пакета, тож TCP ділить його на 9 сегментів до 1460 байтів кожен (тут намальовано як один).",Status:"Статус",Body:"Тіло","Sent as":"Надіслано як","12.2 KB in 9 segments":"12.2 KB у 9 сегментах","Page Rendering":"Показ сторінки","Browser displays the content":"Браузер показує вміст","The browser parses the HTML and paints the page. Linked CSS, images and scripts would each start more requests just like this one, reusing the open connection where they can.":"Браузер розбирає HTML і малює сторінку. Пов’язані CSS, зображення і скрипти запускали б нові запити, такі самі, як цей, і де можна використовували б те саме відкрите з’єднання.",Document:"Документ",Connection:"З’єднання","Kept open for reuse":"Залишається відкритим для повторного використання","Seen on the laptop’s home network":"Як видно в домашній мережі ноутбука",Destination:"Призначення","The router: anything beyond the home network goes to it first.":"Маршрутизатор: усе за межами домашньої мережі спершу йде до нього.",Source:"Джерело","The laptop’s network card.":"Мережева карта ноутбука.",Type:"Тип","What the frame carries.":"Що несе кадр.","Version, header length":"Версія, довжина заголовка","IPv4, with no options.":"IPv4, без опцій.","Priority and congestion marks; 0 means ordinary traffic.":"Позначки пріоритету й перевантаження; 0 означає звичайний трафік.","Total length":"Загальна довжина","This header and everything inside it.":"Цей заголовок і все, що всередині.",Identification:"Ідентифікація","Lets the receiver reassemble the pieces if the packet gets split.":"Дає змогу одержувачу зібрати частини докупи, якщо пакет буде розділено.",Flags:"Прапорці",none:"немає","Routers may split it if a link is too small.":"Маршрутизатори можуть розділити його, якщо канал замалий.","Time to live":"Час життя","Windows starts at 128.":"Windows починає з 128.",Protocol:"Протокол","Header checksum":"Контрольна сума заголовка","Covers this header only; every router recomputes it after lowering the TTL.":"Охоплює лише цей заголовок; кожен маршрутизатор перераховує її, зменшивши TTL.","Source port":"Порт джерела","Destination port":"Порт призначення",Length:"Довжина","UDP header and data. That is all of UDP: no numbering, no acknowledgements.":"Заголовок UDP і дані. Ось і весь UDP: ні нумерації, ні підтверджень.",Checksum:"Контрольна сума","Covers the header, the data and the IP addresses.":"Охоплює заголовок, дані та IP-адреси.","Transaction ID":"Ідентифікатор транзакції","Picked at random; the answer must carry the same one.":"Обирається випадково; відповідь має містити такий самий.","0x0100: query, RD (recursion desired)":"0x0100: запит, RD (бажана рекурсія)",Questions:"Питання",Answers:"Відповіді","Authority records":"Авторитетні записи","Additional records":"Додаткові записи",Question:"Питання","www.example.com, type A, class IN":"www.example.com, тип A, клас IN","The laptop.":"Ноутбук.","The router’s side facing the home network.":"Бік маршрутизатора, звернений до домашньої мережі.","Started at 128; 10 routers on the way each took 1.":"Почалося з 128; кожен із 10 маршрутизаторів на шляху відняв 1.","0x8180: response, RD (recursion desired), RA (recursion available)":"0x8180: відповідь, RD (бажана рекурсія), RA (рекурсія доступна)","DF (don’t fragment)":"DF (не фрагментувати)","Routers must not split it; if it’s too big they report back instead.":"Маршрутизатори не можуть його розділяти; якщо він завеликий, вони повідомляють про це назад.","Picked by the laptop’s system for this connection.":"Вибрано системою ноутбука для цього з’єднання.","Sequence number":"Порядковий номер","This side’s starting number. Shown as 0; the real one is random.":"Початковий номер цієї сторони. Показано як 0; справжній — випадковий.","Real sequence number":"Справжній порядковий номер",Acknowledgment:"Підтвердження","0 (not used yet)":"0 (ще не використовується)","A first SYN has nothing to acknowledge.":"Першому SYN нема чого підтверджувати.","Header length":"Довжина заголовка","20 bytes, plus 12 of options.":"20 байтів плюс 12 байтів опцій.",Window:"Вікно","How much more data this side can take right now.":"Скільки ще даних ця сторона може прийняти зараз.","Covers the header, the data and the IP addresses, so damage is caught.":"Охоплює заголовок, дані та IP-адреси, щоб помітити пошкодження.","Urgent pointer":"Покажчик терміновості",Options:"Опції","Maximum segment size":"Максимальний розмір сегмента","The most data this side wants in one segment.":"Найбільше даних, яке ця сторона хоче отримувати в одному сегменті.","Spacing, so the next option lines up.":"Вирівнювання, щоб наступна опція стала на своє місце.","Window scale":"Масштаб вікна","Window values are multiplied by this, so windows can be larger than 64 KB.":"Значення вікна множаться на це число, тож вікна можуть бути більшими за 64 KB.","SACK permitted":"SACK дозволено",yes:"так","This side understands selective acknowledgements.":"Ця сторона розуміє вибіркові підтвердження.","Started at 64; 12 routers on the way each took 1.":"Почалося з 64; кожен із 12 маршрутизаторів на шляху відняв 1.","The next byte this side expects: everything before it has arrived.":"Наступний байт, на який чекає ця сторона: усе, що перед ним, уже надійшло.","Position of this segment’s first byte, counted from this side’s SYN.":"Позиція першого байта цього сегмента, рахуючи від SYN цієї сторони.",Padding:"Доповнення","Ethernet frames are at least 60 bytes (64 with the checksum the card adds), so short ones are padded.":"Кадри Ethernet мають щонайменше 60 байтів (64 з контрольною сумою, яку додає карта), тож короткі кадри доповнюються.",Text:"Текст","covers bytes not shown here":"охоплює байти, не показані тут","12,500 bytes: the HTML page":"12,500 байтів: HTML-сторінка","The page itself; its contents are not part of the lesson.":"Сама сторінка; її вміст не є частиною уроку.","Secure Web":"Захищений веб","TLS handshake":"Рукостискання TLS","HTTP request":"HTTP-запит","HTTP response":"HTTP-відповідь","HTTPS is HTTP sent through an encrypted TLS connection. TLS proves the server is who it claims to be with a certificate, agrees on fresh encryption keys, and then protects every request and response from being read or changed on the way.":"HTTPS — це HTTP, надісланий через зашифроване з’єднання TLS. TLS доводить сертифікатом, що сервер той, за кого себе видає, узгоджує нові ключі шифрування, а потім захищає кожен запит і відповідь від читання чи зміни дорогою.","Application (HTTP over TLS)":"Прикладний (HTTP поверх TLS)",Security:"Безпека","TLS 1.3 (1.2 still common)":"TLS 1.3 (1.2 ще поширений)",Proves:"Доводить","Server identity (certificate)":"Особу сервера (сертифікат)","Secure page delivered":"Захищену сторінку доставлено","Encrypted, except the lookup":"Усе зашифровано, крім пошуку адреси","The browser looked up the address in plain DNS, opened a TCP connection, checked the server’s certificate and agreed on keys in one round trip. Every HTTP byte after that travelled encrypted. Press REPLAY to watch it again.":"Браузер знайшов адресу через звичайний DNS, відкрив TCP-з’єднання, перевірив сертифікат сервера й узгодив ключі за один обмін туди-назад. Кожен байт HTTP після цього йшов зашифрованим. Натисніть ЗНОВУ, щоб переглянути ще раз.",Cipher:"Шифр","Still visible":"Досі видно","IPs, server name, sizes":"IP-адреси, ім’я сервера, розміри","Secure Request":"Захищений запит","Browser asks for https://":"Браузер запитує https://","You type https://www.example.com. The “s” tells the browser to protect the connection with TLS, on port 443 by default. Before it can connect at all, it still has to find the server’s IP address.":"Ви вводите https://www.example.com. Літера «s» каже браузеру захистити з’єднання за допомогою TLS, типово на порту 443. Але щоб узагалі під’єднатися, йому все одно треба знайти IP-адресу сервера.",Port:"Порт","DNS Lookup":"Пошук у DNS","Same lookup as HTTP, not encrypted":"Такий самий пошук, як для HTTP, без шифрування","The lookup is exactly the same as for plain HTTP: a query to 8.8.8.8 over UDP port 53. It is not encrypted, so anyone on the path can see which name you asked for, unless the browser uses DNS over HTTPS.":"Пошук точнісінько такий самий, як для звичайного HTTP: запит до 8.8.8.8 через UDP-порт 53. Він не зашифрований, тож будь-хто на шляху бачить, яке ім’я ви запитали, якщо браузер не використовує DNS over HTTPS.",Encrypted:"Зашифровано","No (plain DNS)":"Ні (звичайний DNS)","TCP Handshake":"TCP-рукостискання","Opens a connection to port 443":"Відкриває з’єднання з портом 443","TLS rides on TCP, so the same three-way handshake comes first, this time to port 443. Nothing is encrypted yet.":"TLS працює поверх TCP, тож спершу відбувається те саме тристороннє рукостискання, цього разу з портом 443. Поки що нічого не зашифровано.","TLS Handshake":"TLS-рукостискання","Agrees on keys, checks the certificate":"Узгоджує ключі, перевіряє сертифікат","The browser offers ciphers and key shares, including a post-quantum hybrid. The server picks it and sends its own share, then its certificate, already encrypted. The browser checks it against authorities it trusts.":"Браузер пропонує шифри й частки ключа, зокрема постквантовий гібрид. Сервер вибирає його й надсилає свою частку, а потім сертифікат, уже зашифрованим. Браузер перевіряє сертифікат за центрами, яким довіряє.",Version:"Версія","Key exchange":"Обмін ключами","X25519MLKEM768 (hybrid)":"X25519MLKEM768 (гібрид)","Server name":"Ім’я сервера","Sent in clear (SNI)":"Надсилається відкрито (SNI)","key shares: hybrid + x25519":"частки ключа: гібрид + x25519","cipher: AES_128_GCM_SHA256":"шифр: AES_128_GCM_SHA256","then encrypted: cert, Finished":"далі зашифровано: сертифікат, Finished","handshake complete (encrypted)":"рукостискання завершено (зашифровано)","Encrypted Exchange":"Шифрований обмін","HTTP inside TLS records":"HTTP усередині записів TLS","The GET and 200 OK are the same HTTP messages as before, sealed in TLS records that look like random “application data” on the wire. The server also hands over two session tickets, so a later visit can skip part of the handshake.":"GET і 200 OK — ті самі HTTP-повідомлення, що й раніше, запечатані в записи TLS, які на лінії виглядають як випадкові «дані застосунку». Сервер також передає два сеансові квитки, щоб наступного разу можна було пропустити частину рукостискання.",Inside:"Усередині","GET / and 200 OK":"GET / і 200 OK",Tickets:"Квитки","2, for faster reconnects":"2, для швидшого повторного з’єднання","inside: GET / HTTP/1.1":"усередині: GET / HTTP/1.1","outside: encrypted bytes":"ззовні: зашифровані байти","inside: HTTP/1.1 200 OK":"усередині: HTTP/1.1 200 OK","outside: 12.9 KB, 9 segments":"ззовні: 12.9 KB, 9 сегментів","Browser shows the padlock":"Браузер показує замок","The browser decrypts the response, paints the page and shows a padlock: the connection is private and the server proved its identity. The Strict-Transport-Security header tells it to use HTTPS for this site from now on.":"Браузер розшифровує відповідь, малює сторінку й показує замок: з’єднання приватне, і сервер довів свою особу. Заголовок Strict-Transport-Security каже йому відтепер використовувати для цього сайту лише HTTPS.",Remembers:"Запам’ятовує","HTTPS only (HSTS), 1 year":"Лише HTTPS (HSTS), 1 рік","Server Hello + encrypted handshake, 3 segments":"Server Hello + зашифроване рукостискання, 3 сегменти","Change Cipher Spec, Finished (encrypted)":"Change Cipher Spec, Finished (зашифровано)","Application Data (HTTP request)":"Application Data (HTTP-запит)","New Session Ticket ×2 (encrypted)":"New Session Ticket ×2 (зашифровано)","Application Data (HTTP response), 9 segments":"Application Data (HTTP-відповідь), 9 сегментів",Record:"Запис","Content type":"Тип вмісту","A Client Hello’s record says TLS 1.0 so old middleboxes let it through; the real versions are offered inside.":"Запис Client Hello вказує TLS 1.0, щоб старі проміжні пристрої його пропустили; справжні версії пропонуються всередині.","Handshake type":"Тип рукостискання",Contents:"Вміст","Everything the browser supports. Browsers vary a few details from one connection to the next.":"Усе, що підтримує браузер. Браузери змінюють деякі деталі від з’єднання до з’єднання.","Server name (SNI)":"Ім’я сервера (SNI)","Versions offered":"Запропоновані версії","Key shares":"Частки ключа","App protocols (ALPN)":"Прикладні протоколи (ALPN)","TLS 1.3 records say 1.2 on the outside, for compatibility.":"Записи TLS 1.3 ззовні вказують 1.2, для сумісності.","The server’s choices and its half of the hybrid key exchange.":"Вибір сервера і його половина гібридного обміну ключами.","Cipher suite":"Набір шифрів","Key share":"Частка ключа","Has no job in TLS 1.3; sent so middleboxes see a familiar handshake.":"У TLS 1.3 не має жодної ролі; надсилається, щоб проміжні пристрої бачили знайоме рукостискання.","Every encrypted record says Application Data on the outside; the real type is inside.":"Кожен зашифрований запис ззовні вказує Application Data; справжній тип — усередині.","Encrypted data":"Зашифровані дані","Ciphertext, ending in a 16-byte tag that shows any change. Only the two ends can read it.":"Шифротекст, що закінчується 16-байтовим тегом, який виявляє будь-яку зміну. Прочитати його можуть лише дві сторони.","Encrypted Extensions (ALPN: http/1.1), Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions (ALPN: http/1.1), Certificate (ланцюжок), Certificate Verify (підпис), Finished","Finished: a check value over the whole handshake":"Finished: контрольне значення для всього рукостискання","The HTTP request":"HTTP-запит","New Session Ticket: lets a later visit resume":"New Session Ticket: дає змогу наступному візиту відновити сеанс","The HTTP response, then the 12,500-byte page":"HTTP-відповідь, а потім сторінка на 12,500 байтів","Reliable Delivery":"Надійна доставка","Handshake and ACKs":"Рукостискання та ACK","Data from laptop":"Дані від ноутбука","Data from server":"Дані від сервера","Closing (FIN)":"Закриття (FIN)","TCP turns the internet’s best-effort packet delivery into a reliable, ordered stream of bytes. It numbers every byte, acknowledges what arrives, resends what goes missing, and paces the sender so neither the other side nor the network is overwhelmed.":"TCP перетворює доставку пакетів в інтернеті «як вийде» на надійний упорядкований потік байтів. Він нумерує кожен байт, підтверджує те, що надійшло, повторно надсилає втрачене і стримує відправника, щоб не перевантажити ні іншу сторону, ні мережу.","Transport (Layer 4)":"Транспортний (рівень 4)","Three-way handshake":"Тристороннє рукостискання",Reliability:"Надійність","Sequence numbers + ACKs":"Порядкові номери + ACK",Recovery:"Відновлення",Retransmission:"Повторна передача",Header:"Заголовок","Connection closed":"З’єднання закрито","Every byte accounted for":"Жоден байт не загублено","TCP opened a connection, numbered and acknowledged every byte, spotted a gap and resent just the missing segment, then closed both directions cleanly. curl received every byte in order and never saw the loss. Press REPLAY to watch it again.":"TCP відкрив з’єднання, пронумерував і підтвердив кожен байт, помітив прогалину й повторно надіслав лише відсутній сегмент, а потім чисто закрив обидва напрямки. curl отримав усі байти по порядку й навіть не помітив утрати. Натисніть ЗНОВУ, щоб переглянути ще раз.",Segments:"Сегменти","14 (1 lost, 1 resent)":"14 (1 втрачено, 1 повторено)","Bytes delivered":"Доставлено байтів","78 up, 2,920 down":"78 туди, 2,920 назад","Loss found by":"Утрату виявлено через","Duplicate ACK + SACK":"Дубль ACK + SACK","Open Connection":"Нове з’єднання","curl already knows the server’s address. Before any data moves, both sides choose a starting sequence number and confirm it: SYN, SYN-ACK, ACK. The numbers here are relative; real ones start at a random value.":"curl уже знає адресу сервера. Перш ніж передати будь-які дані, обидві сторони вибирають початковий порядковий номер і підтверджують його: SYN, SYN-ACK, ACK. Номери тут відносні; справжні починаються з випадкового значення.",Server:"Сервер","203.0.113.10, port 80":"203.0.113.10, порт 80","Send Data":"Надсилання даних","Every byte is numbered":"Кожен байт пронумеровано","curl sends its 78-byte HTTP request: bytes 1 to 78. The server’s ACK number, 79, is the next byte it expects, which means everything before it has arrived.":"curl надсилає свій HTTP-запит на 78 байтів: байти з 1 до 78. Номер ACK сервера, 79, — це наступний байт, на який він чекає, тобто все, що перед ним, уже надійшло.",Sent:"Надіслано","79 = next byte expected":"79 = наступний очікуваний байт","Two Segments Back":"Два сегменти назад","One of them is lost":"Один із них губиться","The server answers with 2,920 bytes: two full segments of 1,460 bytes, the most that fits in one packet here, sent back to back. The first is dropped somewhere on the internet; the second gets through.":"Сервер відповідає 2,920 байтами: два повні сегменти по 1,460 байтів, найбільше, що тут вміщується в один пакет, надіслані один за одним. Перший губиться десь в інтернеті; другий доходить.","Segment 1":"Сегмент 1","bytes 1–1460 (lost)":"байти 1–1460 (втрачено)","Segment 2":"Сегмент 2","Segment size":"Розмір сегмента","seq=1 and seq=1461":"seq=1 і seq=1461","the first is lost":"перший губиться","A Gap Is Noticed":"Видно прогалину","Duplicate ACK with SACK":"Дубль ACK із SACK","Bytes 1461–2920 arrive, but 1–1460 never did. An ACK can only count bytes received in order, so the laptop repeats ACK 1 at once and adds a SACK block saying it already holds 1461–2920.":"Байти 1461–2920 надходять, а 1–1460 так і ні. ACK може рахувати лише байти, отримані по порядку, тож ноутбук одразу повторює ACK 1 і додає блок SACK, який каже, що 1461–2920 у нього вже є.","1 (still waiting for byte 1)":"1 (досі чекає на байт 1)","holds bytes 1461–2920":"має байти 1461–2920","At once, not delayed":"Одразу, без затримки","sack: has 1461–2920":"sack: має 1461–2920","Resend the Gap":"Повтор прогалини","Only the missing bytes":"Лише відсутні байти","The SACK tells the server exactly what is missing, so it resends just segment 1, and the laptop acknowledges everything. Had no ACK come back at all, timers would have stepped in: a probe after about two round trips, then a retransmission timeout (at least 200 ms on Linux).":"SACK точно каже серверу, чого бракує, тож він повторно надсилає лише сегмент 1, а ноутбук підтверджує все. Якби жоден ACK не повернувся, втрутилися б таймери: пробний пакет приблизно через два обміни туди-назад, а потім тайм-аут повторної передачі (у Linux щонайменше 200 ms).",Resent:"Повторено","bytes 1–1460 only":"лише байти 1–1460","Next ACK":"Наступний ACK","2921 (everything)":"2921 (усе)","curl saw":"curl побачив","Every byte, in order":"Кожен байт, по порядку","just the missing segment":"лише відсутній сегмент","Close Connection":"Кінець з’єднання","Each side says goodbye":"Кожна сторона прощається","curl is done, so it closes. Each direction closes on its own: the laptop sends FIN and the server acknowledges it, then the server sends its own FIN and the laptop acknowledges that. The laptop keeps the connection’s details for a while (TIME-WAIT).":"curl закінчив, тож закриває з’єднання. Кожен напрямок закривається окремо: ноутбук надсилає FIN, сервер його підтверджує, потім сервер надсилає свій FIN, а ноутбук підтверджує його. Ноутбук ще якийсь час зберігає дані про з’єднання (TIME-WAIT).","Closed by":"Закрито через","A FIN from each side":"FIN від кожної сторони",Order:"Порядок",Then:"Потім","Laptop waits (TIME-WAIT)":"Ноутбук чекає (TIME-WAIT)",Data:"Дані","1,460 bytes: the HTTP response, bytes 1–1460":"1,460 байтів: HTTP-відповідь, байти 1–1460","1,460 bytes: the HTTP response, bytes 1461–2920":"1,460 байтів: HTTP-відповідь, байти 1461–2920","has 1461–2920":"має 1461–2920","Bytes that arrived after the gap, so only the gap needs resending.":"Байти, що надійшли після прогалини, тож повторно надіслати треба лише прогалину.","Fast Datagrams":"Швидкі датаграми","Your voice":"Ваш голос","Their voice":"Голос співрозмовника","Media Server":"Медіасервер","UDP sends data in independent packets called datagrams, with no connection, no acknowledgements and no resends. That keeps it fast and light: right for voice, video, games and DNS, where a late answer is worse than a missing one.":"UDP надсилає дані незалежними пакетами — датаграмами, без з’єднання, без підтверджень і без повторів. Це робить його швидким і легким: саме те для голосу, відео, ігор і DNS, де запізніла відповідь гірша за відсутню.",None:"Немає","None (no ACKs, no resends)":"Немає (ні ACK, ні повторів)",Ordering:"Порядок","Not guaranteed":"Не гарантовано","Call keeps flowing":"Дзвінок триває","Fast, simple, no guarantees":"Швидко, просто, без гарантій","Audio started with the very first packet, every datagram travelled on its own, and the one that was lost was simply gone: UDP never noticed. The app covered the gap and the call carried on. Press REPLAY to watch it again.":"Звук пішов із найпершим пакетом, кожна датаграма мандрувала сама по собі, а втрачена просто зникла: UDP цього навіть не помітив. Застосунок приховав прогалину, і дзвінок тривав. Натисніть ЗНОВУ, щоб переглянути ще раз.",Datagrams:"Датаграми","11 (1 lost, never resent)":"11 (1 втрачено, не повторено)","Setup time":"Час налаштування","0 ms (no handshake)":"0 ms (без рукостискання)",Shown:"Показано","The first 0.2 s of a call":"Перші 0.2 s дзвінка","Send Right Away":"Надсилання одразу","No handshake, data goes first":"Без рукостискання, дані йдуть першими","A call app already knows the media server’s address and port from signing in. It doesn’t open a connection: the very first datagram already carries 20 ms of your voice, behind an 8-byte UDP header.":"Застосунок для дзвінків уже знає адресу й порт медіасервера з моменту входу. Він не відкриває з’єднання: найперша датаграма вже несе 20 ms вашого голосу за 8-байтовим заголовком UDP.",Setup:"Налаштування",Ports:"Порти","92 B of audio, no setup":"92 B звуку, без налаштування","A Stream of Datagrams":"Потік датаграм","One every 20 ms, each on its own":"Одна кожні 20 ms, кожна сама по собі","The app keeps sending a datagram every 20 ms. Each one stands alone, with its own header and no link to the others. UDP doesn’t number them, and nothing comes back to confirm they arrived.":"Застосунок і далі надсилає датаграму кожні 20 ms. Кожна з них самостійна, має власний заголовок і не пов’язана з іншими. UDP їх не нумерує, і назад нічого не приходить на підтвердження, що вони дійшли.",Rate:"Темп","1 datagram / 20 ms":"1 датаграма / 20 ms",Numbering:"Нумерація","None in UDP itself":"У самому UDP немає",Confirmation:"Підтвердження","None (no ACKs)":"Немає (без ACK)","voice frames 2–5":"голосові кадри 2–5","each with its own 8-byte header":"кожен із власним 8-байтовим заголовком","Lost on the Way":"Утрачено дорогою","Nobody resends it":"Ніхто не надсилає його знову","Frame 7 is dropped somewhere on the internet. The media server never asks for it, and UDP never tells the laptop: there are no acknowledgements to miss. The datagrams after it arrive as normal.":"Кадр 7 губиться десь в інтернеті. Медіасервер ніколи його не запитує, а UDP ніколи не повідомляє ноутбук: тут немає підтверджень, відсутність яких можна помітити. Датаграми після нього надходять як завжди.",Lost:"Утрачено","Voice frame 7":"Голосовий кадр 7","Never (no ACKs)":"Ніколи (без ACK)",Missing:"Бракує","20 ms of audio":"20 ms звуку","voice frames 6–8":"голосові кадри 6–8","frame 7 is lost":"кадр 7 губиться","Replies Come Back":"Ідуть відповіді","The other voice comes back":"Повертається інший голос","The other person’s voice arrives the same way, as separate datagrams sent to port 50000. They get back in because your router remembered the outgoing port when it translated your address (NAT).":"Голос співрозмовника надходить так само, окремими датаграмами на порт 50000. Вони потрапляють усередину, бо ваш маршрутизатор запам’ятав вихідний порт, коли транслював вашу адресу (NAT).",Direction:"Напрямок","Independent of ours":"Незалежно від нашого","Through NAT":"Через NAT","Router remembers the port":"Маршрутизатор пам’ятає порт","the other person’s voice":"голос співрозмовника","sent to port 50000":"надіслано на порт 50000","The App Decides":"Вирішує застосунок","Reliability is up to the app":"Надійність — справа застосунку","The call app numbers its own frames (RTP does this), so it sees that frame 7 is missing and smooths over the 20 ms gap instead of waiting. Waiting for a resend would make the whole call lag.":"Застосунок для дзвінків сам нумерує свої кадри (це робить RTP), тож бачить, що кадру 7 бракує, і згладжує прогалину в 20 ms, а не чекає. Очікування повтору змусило б увесь дзвінок відставати.","App’s job (e.g. RTP)":"Справа застосунку (напр. RTP)",Loss:"Утрати","Hidden by the app":"Приховує застосунок","Also on UDP":"Теж на UDP","DNS, games, QUIC":"DNS, ігри, QUIC","Version etc.":"Версія тощо","2, no padding, no extension, no CSRCs":"2, без доповнення, без розширення, без CSRC","Marker, payload type":"Маркер, тип даних","1, 111 (Opus, agreed when the call was set up)":"1, 111 (Opus, узгоджено під час встановлення дзвінка)","Counts up by one per packet, so the app can spot a missing or late one.":"Збільшується на одиницю з кожним пакетом, тож застосунок помічає відсутній чи запізнілий.",Timestamp:"Мітка часу","Audio clock at 48,000 per second: +960 per 20 ms frame.":"Аудіогодинник на 48,000 за секунду: +960 на кожен кадр у 20 ms.","Identifies this audio stream.":"Позначає цей аудіопотік.",Audio:"Аудіо","80 bytes of Opus audio (20 ms)":"80 байтів звуку Opus (20 ms)","0, 111 (Opus, agreed when the call was set up)":"0, 111 (Opus, узгоджено під час встановлення дзвінка)","Addressing & Routing":"Адресація та маршрутизація","Outgoing packet":"Вихідний пакет",Reply:"Відповідь","IP gives every device an address and moves packets from network to network. Each router looks only at the destination address to choose the next hop. IP is best effort: it doesn’t promise delivery or order. TCP adds those on top.":"IP дає кожному пристрою адресу й переносить пакети з мережі в мережу. Кожен маршрутизатор дивиться лише на адресу призначення, щоб вибрати наступний хоп. IP працює за принципом «як вийде»: він не обіцяє ні доставки, ні порядку. Це додає TCP поверх нього.","Network (Layer 3)":"Мережевий (рівень 3)",Address:"Адреса","Lowered by 1 at each router":"Зменшується на 1 на кожному маршрутизаторі",Delivery:"Доставка","Best effort":"Як вийде","There and back":"Туди й назад","Twelve routers each way":"По дванадцять маршрутизаторів у кожен бік","The laptop sent the packet to its router, which swapped in its public address. Twelve routers in all passed it along by destination address alone, and the reply found its way back the same way. Press REPLAY to watch it again.":"Ноутбук надіслав пакет своєму маршрутизатору, а той підставив свою публічну адресу. Загалом дванадцять маршрутизаторів передавали його далі лише за адресою призначення, а відповідь так само знайшла шлях назад. Натисніть ЗНОВУ, щоб переглянути ще раз.",Routers:"Маршрутизатори","12 each way (1 home + 11)":"12 у кожен бік (1 домашній + 11)","TTL at server":"TTL на сервері","116 (sent with 128)":"116 (надіслано з 128)","Rewritten by NAT":"Переписує NAT","Source out, destination back":"Джерело туди, призначення назад","IPv4 (IPv6 works alike)":"IPv4 (IPv6 працює так само)","Local or Not?":"Локальна чи ні?","Compare the address with the subnet":"Порівняння адреси з підмережею","The laptop is 192.168.1.10 with a /24 mask, so its own network is 192.168.1.0 to 192.168.1.255. The server, 203.0.113.10, is outside that range, so the packet has to go to the default gateway: the home router.":"Ноутбук має адресу 192.168.1.10 з маскою /24, тож його власна мережа — від 192.168.1.0 до 192.168.1.255. Сервер, 203.0.113.10, поза цим діапазоном, тож пакет має йти до основного шлюзу: домашнього маршрутизатора.",Laptop:"Ноутбук","Local range":"Локальний діапазон",Gateway:"Шлюз","Find the Router":"Де маршрутизатор?","ARP turns an IP into a MAC":"ARP перетворює IP на MAC","On the local network, frames are delivered by MAC address. If the router’s MAC isn’t in the laptop’s ARP cache, it broadcasts “who has 192.168.1.1?” and the router answers with its MAC address.":"У локальній мережі кадри доставляються за MAC-адресою. Якщо MAC маршрутизатора немає в ARP-кеші ноутбука, той розсилає всім «хто має 192.168.1.1?», і маршрутизатор відповідає своєю MAC-адресою.",Asks:"Питає","Who has 192.168.1.1?":"Хто має 192.168.1.1?","Sent to":"Кому","Everyone (broadcast)":"Усім (широкомовно)",Learns:"Дізнається","Router’s MAC address":"MAC-адресу маршрутизатора","who has 192.168.1.1?":"хто має 192.168.1.1?","tell 192.168.1.10":"скажіть 192.168.1.10","Send the Packet":"Надсилання пакета","Addresses, TTL and protocol":"Адреси, TTL і протокол","The IP header carries the source and destination addresses, a TTL and the protocol inside. Here it holds a TCP SYN to port 443. Windows starts the TTL at 128 (Linux and macOS use 64).":"Заголовок IP містить адреси джерела й призначення, TTL і протокол усередині. Тут у ньому TCP SYN на порт 443. Windows починає TTL зі 128 (Linux і macOS — з 64).","From → to":"Звідки → куди","TTL 128 · protocol TCP":"TTL 128 · протокол TCP","NAT, Then Hop by Hop":"NAT і хоп за хопом","The router rewrites and forwards":"Маршрутизатор переписує й пересилає","The router swaps the private source for its public address 198.51.100.7 (and here port 52344 for 40112), notes the mapping, and lowers the TTL to 127. Then 11 routers on the internet each choose the next hop by destination and lower the TTL again.":"Маршрутизатор замінює приватне джерело своєю публічною адресою 198.51.100.7 (а тут ще порт 52344 на 40112), записує цю відповідність і зменшує TTL до 127. Потім 11 маршрутизаторів в інтернеті кожен вибирають наступний хоп за адресою призначення й знову зменшують TTL.","New source":"Нове джерело","Leaves home":"Виходить із дому","At the server":"На сервері","TTL 116 (11 more hops)":"TTL 116 (ще 11 хопів)","TTL 127 · after NAT":"TTL 127 · після NAT","The Reply Comes Back":"Відповідь назад","NAT translates it for the laptop":"NAT транслює її для ноутбука","The server answers the address it saw, 198.51.100.7:40112. The router looks that up in its NAT table, rewrites the destination back to 192.168.1.10:52344 and passes it on. The reply started at TTL 64 and arrives with 52.":"Сервер відповідає на адресу, яку бачив, 198.51.100.7:40112. Маршрутизатор шукає її у своїй таблиці NAT, переписує призначення назад на 192.168.1.10:52344 і передає далі. Відповідь вирушила з TTL 64 і надходить із 52.","Delivered to":"Доставлено","TTL 52 · after NAT":"TTL 52 · після NAT","TTL 127 · 40112 → 443 [SYN] (after NAT)":"TTL 127 · 40112 → 443 [SYN] (після NAT)","TTL 52 · 443 → 52344 [SYN, ACK] (after NAT)":"TTL 52 · 443 → 52344 [SYN, ACK] (після NAT)","ARP request · 28 bytes":"ARP-запит · 28 байтів","Broadcast: every device on the network receives it.":"Широкомовно: його отримує кожен пристрій у мережі.","The sender’s network card.":"Мережева карта відправника.","Hardware type":"Тип обладнання","Protocol type":"Тип протоколу","Address sizes":"Розміри адрес",Operation:"Операція","1 (request: who has …?)":"1 (запит: хто має …?)","Sender MAC":"MAC відправника","Sender IP":"IP відправника","Target MAC":"MAC цілі","All zeros: this is what the request wants to find out.":"Самі нулі: саме це запит і хоче з’ясувати.","Target IP":"IP цілі","ARP reply · 28 bytes":"ARP-відповідь · 28 байтів","Straight back to the device that asked.":"Прямо назад пристрою, що питав.","2 (reply: … is at …)":"2 (відповідь: … має …)","Seen as it leaves the router’s internet side":"Як видно на виході з інтернет-боку маршрутизатора","The internet provider’s router, the next hop.":"Маршрутизатор інтернет-провайдера, наступний хоп.","The router’s internet-facing port.":"Порт маршрутизатора, звернений до інтернету.","As sent: this system starts at 64.":"Як надіслано: ця система починає з 64.","The router’s NAT swapped in its own port for the laptop’s.":"NAT маршрутизатора підставив власний порт замість порту ноутбука.","The sender’s next router; each hop puts the packet in a new frame.":"Наступний маршрутизатор відправника; кожен хоп кладе пакет у новий кадр.","Name Resolution":"Розв’язання імен",Query:"Запит",Referral:"Перенаправлення","DNSSEC not requested here":"DNSSEC тут не запитано","DNS turns names like www.example.com into the IP addresses computers use to reach each other. No single server knows every name: the system is a hierarchy of servers, and answers are cached along the way so most lookups never have to go far.":"DNS перетворює імена на кшталт www.example.com на IP-адреси, за якими комп’ютери знаходять один одного. Жоден сервер не знає всіх імен: система — це ієрархія серверів, а відповіді кешуються дорогою, тож більшість пошуків не мусять іти далеко.","53, UDP (TCP if large)":"53, UDP (TCP, якщо великий)",Turns:"Перетворює","Names into IP addresses":"Імена на IP-адреси",Hierarchy:"Ієрархія","Root → TLD → authoritative":"Корінь → TLD → авторитетний",Caching:"Кешування","For each record’s TTL":"На час TTL кожного запису","Name resolved":"Ім’я розв’язано","And remembered for an hour":"І запам’ятовано на годину","Starting from an empty cache, the resolver walked from the root to .com to example.com’s own server, then answered the laptop. Until the TTL runs out, the next lookup for this name is answered straight from a cache. Press REPLAY to watch it again.":"Почавши з порожнього кешу, резолвер пройшов від кореня до .com і до власного сервера example.com, а потім відповів ноутбуку. Доки не мине TTL, наступний пошук цього імені отримає відповідь прямо з кешу. Натисніть ЗНОВУ, щоб переглянути ще раз.",Queries:"Запити","4 (laptop 1, resolver 3)":"4 (ноутбук 1, резолвер 3)","Cached for":"У кеші на","Ask the Resolver":"Питання резолверу","The laptop hands the question off":"Ноутбук передає питання далі","The browser needs the IP address of www.example.com and neither it nor Windows has one cached. The laptop sends one question to the recursive resolver it was given, 8.8.8.8, and asks it to do the whole lookup (recursion desired).":"Браузерові потрібна IP-адреса www.example.com, а ні в нього, ні у Windows її немає в кеші. Ноутбук надсилає одне питання рекурсивному резолверу, який йому видали, 8.8.8.8, і просить виконати весь пошук (бажана рекурсія).","www.example.com, type A":"www.example.com, тип A",Asked:"Запитано","8.8.8.8 (recursive)":"8.8.8.8 (рекурсивний)","RD (recursion desired)":"RD (бажана рекурсія)","flags: RD":"прапорці: RD","Points the way to .com":"Вказує шлях до .com","The resolver’s cache is empty (it has just started), so it begins at the top. A root server doesn’t know the address, but it knows which servers handle .com and replies with a referral. Many resolvers send it only “com”, not the full name.":"Кеш резолвера порожній (він щойно запустився), тож він починає з самої вершини. Кореневий сервер не знає адреси, але знає, які сервери обслуговують .com, і відповідає перенаправленням. Багато резолверів надсилають йому лише «com», а не повне ім’я.","Root servers":"Кореневі сервери","13 names, 1,000+ anycast sites":"13 імен, 1,000+ anycast-вузлів","Referral (13 .com servers)":"Перенаправлення (13 серверів .com)","no answer: ask .com":"відповіді немає: питайте .com","Points the way to example.com":"Вказує шлях до example.com","The resolver asks one of the .com servers. They don’t store addresses for every site either, but they know which name servers each .com domain uses, so this reply is another referral, with those servers’ addresses (glue) attached.":"Резолвер питає один із серверів .com. Вони теж не зберігають адрес усіх сайтів, але знають, якими серверами імен користується кожен домен .com, тож ця відповідь — ще одне перенаправлення, з доданими адресами цих серверів (glue).",Knows:"Знає","Name servers of .com domains":"Сервери імен доменів .com","Referral + glue addresses":"Перенаправлення + адреси glue","no answer: ask example.com":"відповіді немає: питайте example.com","Gives the actual answer":"Дає справжню відповідь","Finally the resolver asks example.com’s own name server, which holds the domain’s records. It answers with the A record and marks the reply authoritative. The domain owner sets how long it may be cached: here, 3600 seconds.":"Нарешті резолвер питає власний сервер імен example.com, де зберігаються записи домену. Той відповідає записом A і позначає відповідь як авторитетну. Власник домену задає, як довго її можна кешувати: тут 3600 секунд.","AA (authoritative), TTL 3600":"AA (авторитетна), TTL 3600","TTL 3600 · flag AA":"TTL 3600 · прапорець AA","Answer & Cache":"Відповідь і кеш","The laptop gets its address":"Ноутбук отримує адресу","The resolver sends the answer back to the laptop and keeps a copy. For the next hour it can answer this name straight away, which is why the lookup in the HTTP lesson took only 24 ms. The laptop caches it too.":"Резолвер надсилає відповідь ноутбуку й зберігає копію. Наступну годину він може відповідати на це ім’я одразу, тому пошук в уроці HTTP тривав лише 24 ms. Ноутбук теж її кешує.","RD, RA (recursion available)":"RD, RA (рекурсія доступна)","Cached by":"Кешують","Resolver and laptop":"Резолвер і ноутбук","flags: RD RA":"прапорці: RD RA","Referral: com. NS ×13 (with glue)":"Перенаправлення: com. NS ×13 (з glue)","Referral: example.com. NS ×2 (with glue)":"Перенаправлення: example.com. NS ×2 (з glue)","Response A 203.0.113.10 (authoritative)":"Відповідь A 203.0.113.10 (авторитетна)","As sent: this system starts at 128.":"Як надіслано: ця система починає з 128.","0x0000: query":"0x0000: запит","UDP size 1232, DNSSEC OK = 0":"Розмір UDP 1232, DNSSEC OK = 0","Says how big a UDP answer can be. DNSSEC signatures are not asked for here, to keep the lesson short; a validating resolver like 8.8.8.8 does ask for them.":"Каже, наскільки великою може бути відповідь UDP. Підписи DNSSEC тут не запитуються, щоб урок був коротшим; резолвер із перевіркою, як-от 8.8.8.8, запитує їх.","0x8000: response":"0x8000: відповідь",Authority:"Повноваження",Additional:"Додатково","0x8400: response, AA (authoritative)":"0x8400: відповідь, AA (авторитетна)","Getting an Address":"Отримання адреси","From the laptop":"Від ноутбука","From the DHCP server":"Від DHCP-сервера","Dynamic Host Configuration Protocol":"Протокол динамічного налаштування хостів","DHCP hands a device everything it needs to use a network: an IP address, the subnet mask, the router to send traffic through and the DNS servers to ask. Addresses are leased for a set time and renewed while the device stays on the network.":"DHCP видає пристрою все, що потрібно для роботи в мережі: IP-адресу, маску підмережі, маршрутизатор, через який слати трафік, і DNS-сервери, до яких звертатися. Адреси видаються в оренду на певний час і поновлюються, поки пристрій лишається в мережі.","UDP 67 (server), 68 (client)":"UDP 67 (сервер), 68 (клієнт)","Hands out":"Видає","IP, mask, gateway, DNS":"IP, маску, шлюз, DNS",Exchange:"Обмін",Lease:"Оренда","Renewed at half its time":"Поновлюється на половині строку","On the network":"У мережі","Leased, and kept up to date":"Адресу орендовано й оновлюється","Four messages took the laptop from no address to a working configuration, and halfway through the 24-hour lease it renewed it with a direct request to the router. Press REPLAY to watch it again.":"Чотири повідомлення провели ноутбук від відсутності адреси до робочих налаштувань, а на половині 24-годинної оренди він поновив її прямим запитом до маршрутизатора. Натисніть ЗНОВУ, щоб переглянути ще раз.",Messages:"Повідомлення","4 to join, 2 per renewal":"4 для входу, 2 на поновлення","24 h, renewed at 12 h":"24 h, поновлення через 12 h","No Address Yet":"Ще немає адреси","The laptop joins the network":"Ноутбук приєднується до мережі","The laptop has just connected. It has a MAC address built in, but no IP address, no gateway and no DNS server, so it can’t talk to anything beyond its own network yet. It asks for them with DHCP.":"Ноутбук щойно під’єднався. У нього є вбудована MAC-адреса, але немає IP-адреси, шлюзу й DNS-сервера, тож поки що він не може зв’язатися ні з чим за межами своєї мережі. Він запитує їх через DHCP.","IP address":"IP-адреса","None (uses 0.0.0.0)":"Немає (використовує 0.0.0.0)","MAC address":"MAC-адреса",Needs:"Потрібно",Discover:"Discover","Shout to the whole network":"Гукнути на всю мережу","Without an address of its own, the laptop sends from 0.0.0.0 to the broadcast address 255.255.255.255, so every device on the local network receives it. Only DHCP servers answer.":"Не маючи власної адреси, ноутбук надсилає з 0.0.0.0 на широкомовну адресу 255.255.255.255, тож це отримує кожен пристрій у локальній мережі. Відповідають лише DHCP-сервери.",From:"Від","0.0.0.0, UDP port 68":"0.0.0.0, UDP-порт 68","255.255.255.255, port 67":"255.255.255.255, порт 67",Carries:"Несе","MAC, transaction ID":"MAC, ідентифікатор транзакції","any DHCP server out there?":"є тут якийсь DHCP-сервер?",Offer:"Offer","The router proposes an address":"Маршрутизатор пропонує адресу","The router’s DHCP server picks a free address and offers it with the rest of the settings. The laptop can’t use an IP address yet, so the offer goes straight to its MAC address (some clients ask for a broadcast instead).":"DHCP-сервер маршрутизатора вибирає вільну адресу й пропонує її разом з рештою налаштувань. Ноутбук поки не може користуватися IP-адресою, тож пропозиція йде прямо на його MAC-адресу (деякі клієнти просять натомість широкомовної розсилки).",Offered:"Запропоновано","Gateway, DNS":"Шлюз, DNS","offer: 192.168.1.10/24":"пропозиція: 192.168.1.10/24","gateway, DNS, lease 24 h":"шлюз, DNS, оренда 24 h","Accept, out loud":"Прийняти вголос","The laptop asks for the offered address, naming the server it chose. It still broadcasts, so any other DHCP server that made an offer learns it wasn’t picked and can release its address.":"Ноутбук просить запропоновану адресу, називаючи вибраний сервер. Він і далі розсилає широкомовно, тож будь-який інший DHCP-сервер, що зробив пропозицію, дізнається, що його не вибрали, і може звільнити свою адресу.",Requests:"Просить","Chosen server":"Вибраний сервер","I’ll take 192.168.1.10":"Беру 192.168.1.10","from server 192.168.1.1":"від сервера 192.168.1.1",Acknowledge:"Підтвердження","The address is the laptop’s":"Адреса належить ноутбуку","The server confirms, and the laptop configures its address, mask, gateway and DNS server. Many systems first check with ARP that no other device is already using the address.":"Сервер підтверджує, і ноутбук налаштовує адресу, маску, шлюз і DNS-сервер. Багато систем спершу перевіряють через ARP, що жоден інший пристрій уже не використовує цю адресу.","DNS server":"DNS-сервер","192.168.1.10 is yours":"192.168.1.10 — ваша","for 24 hours":"на 24 години",Renew:"Поновлення","Halfway through the lease":"На половині строку оренди","Twelve hours later, half the lease has passed. The laptop now has an address, so it asks the router directly to extend the lease, and the router resets it to 24 hours. If the router didn’t answer, it would broadcast at 87.5%.":"Через дванадцять годин минає половина строку оренди. Тепер ноутбук має адресу, тож просить маршрутизатор напряму продовжити оренду, і маршрутизатор знову встановлює її на 24 години. Якби маршрутизатор не відповів, ноутбук розіслав би запит широкомовно на 87.5%.",When:"Коли","50% of lease (T1 = 12 h)":"50% оренди (T1 = 12 h)","The router (unicast)":"Маршрутизатор (адресно)","If unanswered":"Якщо без відповіді","Broadcast at 87.5% (T2)":"Широкомовно на 87.5% (T2)","renew 192.168.1.10":"поновити 192.168.1.10","sent straight to 192.168.1.1":"надіслано прямо на 192.168.1.1","lease renewed":"оренду поновлено","another 24 hours":"ще 24 години",Message:"Повідомлення","1 (request, from a client)":"1 (запит від клієнта)",Hardware:"Обладнання","Ethernet, 6-byte addresses":"Ethernet, 6-байтові адреси",Hops:"Хопи","Chosen by the client; every reply repeats it.":"Вибирає клієнт; кожна відповідь повторює його.",Seconds:"Секунди","0x0000 (unicast replies are fine)":"0x0000 (адресні відповіді підходять)","Broadcast flag off: the server may send straight to the client’s MAC address.":"Прапорець широкомовлення вимкнено: сервер може надсилати прямо на MAC-адресу клієнта.","Client address":"Адреса клієнта","Filled in only when the client already has an address (renewing).":"Заповнюється, лише коли клієнт уже має адресу (поновлення).","Your address":"Ваша адреса","The address the server is giving out.":"Адреса, яку видає сервер.","Next server":"Наступний сервер","Relay agent":"Агент-ретранслятор","Client MAC":"MAC клієнта","Server name, boot file":"Ім’я сервера, файл завантаження",empty:"порожньо","Magic cookie":"Magic cookie","Marks the options that follow as DHCP.":"Позначає наступні опції як DHCP.","Message type: 1 (Discover)":"Тип повідомлення: 1 (Discover)","Client identifier: 01 00:00:5e:00:53:10":"Ідентифікатор клієнта: 01 00:00:5e:00:53:10","Host name: alice-laptop":"Ім’я хоста: alice-laptop","Vendor class: MSFT 5.0":"Клас постачальника: MSFT 5.0","Parameters wanted: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252":"Потрібні параметри: 1, 3, 6, 15, 31, 33, 43, 44, 46, 47, 119, 121, 249, 252","2 (reply, from a server)":"2 (відповідь від сервера)","Message type: 2 (Offer)":"Тип повідомлення: 2 (Offer)","Server identifier: 192.168.1.1":"Ідентифікатор сервера: 192.168.1.1","Lease time: 86,400 s (24 h)":"Час оренди: 86,400 s (24 h)","Renewal time (T1): 43,200 s (12 h)":"Час поновлення (T1): 43,200 s (12 h)","Rebinding time (T2): 75,600 s (21 h)":"Час переприв’язки (T2): 75,600 s (21 h)","Subnet mask: 255.255.255.0":"Маска підмережі: 255.255.255.0","Broadcast address: 192.168.1.255":"Широкомовна адреса: 192.168.1.255","DNS server: 8.8.8.8":"DNS-сервер: 8.8.8.8","Message type: 3 (Request)":"Тип повідомлення: 3 (Request)","Requested address: 192.168.1.10":"Запитана адреса: 192.168.1.10","Client FQDN: alice-laptop":"FQDN клієнта: alice-laptop","Message type: 5 (ACK)":"Тип повідомлення: 5 (ACK)","Network Diagnostics":"Діагностика мережі","Ping / probe":"Ping / проба","Echo reply":"Ехо-відповідь","Error report":"Звіт про помилку","Internet Control Message Protocol":"Протокол службових повідомлень інтернету","ICMP is how the network reports back: a router says a packet’s time ran out, a server says nothing is listening on a port. Tools like ping and traceroute are built from these messages. It travels inside IP but carries no application data.":"ICMP — це спосіб, яким мережа звітує назад: маршрутизатор каже, що час пакета вичерпано, сервер каже, що на порту ніхто не слухає. Утиліти на кшталт ping і traceroute побудовані з цих повідомлень. ICMP їде всередині IP, але не несе даних застосунків.","Carried in":"Передається в","IP (protocol 1)":"IP (протокол 1)","A type and a code":"Тип і код",Tools:"Утиліти",Often:"Часто","Filtered by firewalls":"Фільтрують брандмауери","The network answered":"Мережа відповіла","Replies, expiries and errors":"Відповіді, вичерпання часу й помилки","An echo request measured the round trip, packets with a small TTL made each router on the path identify itself, and a closed port was reported straight back. Press REPLAY to watch it again.":"Ехо-запит виміряв час туди й назад, пакети з малим TTL змусили кожен маршрутизатор на шляху назватися, а про закритий порт одразу повідомили назад. Натисніть ЗНОВУ, щоб переглянути ще раз.","Round trip":"Туди й назад",Path:"Шлях","12 routers, server at hop 13":"12 маршрутизаторів, сервер на хопі 13","Types used":"Використані типи","8, 0, 11 and 3":"8, 0, 11 і 3","Reply TTL":"TTL відповіді",Ping:"Ping","Echo request":"Ехо-запит","“ping -n 1 203.0.113.10” sends one ICMP echo request (plain ping sends four, a second apart): type 8, code 0, with an identifier, a sequence number and 32 bytes of filler. The server’s system answers by itself, no application needed.":"«ping -n 1 203.0.113.10» надсилає один ICMP ехо-запит (звичайний ping надсилає чотири, з інтервалом у секунду): тип 8, код 0, з ідентифікатором, порядковим номером і 32 байтами заповнювача. Система сервера відповідає сама, без жодного застосунку.","Type, code":"Тип, код","8, 0 (echo request)":"8, 0 (ехо-запит)","type 8 · seq 1":"тип 8 · seq 1","32 bytes of data":"32 байти даних","Echo Reply":"Ехо-відповідь","Round-trip time":"Час туди й назад","The server sends back an echo reply, type 0, with the same identifier, sequence number and data. Ping prints the time it took and the TTL the reply arrived with: “bytes=32 time=34ms TTL=52”.":"Сервер надсилає назад ехо-відповідь, тип 0, з тим самим ідентифікатором, порядковим номером і даними. Ping виводить, скільки це тривало, і TTL, з яким прийшла відповідь: «число байт=32 час=34мс TTL=52».","0, 0 (echo reply)":"0, 0 (ехо-відповідь)","TTL on arrival":"TTL після прибуття","type 0 · seq 1":"тип 0 · seq 1","same 32 bytes back":"ті самі 32 байти назад","The first router answers":"Відповідає перший маршрутизатор","“ping -n 1 -i 1” sends the same request with a TTL of 1. The home router lowers it to 0, so it must drop the packet, and it sends back a Time Exceeded message from its own address: “Reply from 192.168.1.1: TTL expired in transit.”":"«ping -n 1 -i 1» надсилає той самий запит із TTL 1. Домашній маршрутизатор зменшує його до 0, тож мусить відкинути пакет, і надсилає назад повідомлення Time Exceeded (час вичерпано) зі своєї адреси: «Відповідь від 192.168.1.1: Термін дії TTL минув під час передачі.»","Sent with":"Надіслано з","Dropped by":"Відкинув","11, 0 (time exceeded)":"11, 0 (час вичерпано)","echo request":"ехо-запит","expires at the first router":"гине на першому маршрутизаторі","type 11 · from 192.168.1.1":"тип 11 · від 192.168.1.1","quotes the dropped header":"цитує заголовок відкинутого","The next router answers":"Відповідає наступний маршрутизатор","With “-i 2”, the home router lowers the TTL to 1 and forwards it. The first router at the internet provider lowers it to 0 and reports back from 198.51.100.1. The home router translates the report back to the laptop like any reply.":"З «-i 2» домашній маршрутизатор зменшує TTL до 1 і пересилає пакет. Перший маршрутизатор інтернет-провайдера зменшує його до 0 і звітує з 198.51.100.1. Домашній маршрутизатор транслює звіт назад ноутбуку, як і будь-яку відповідь.","ISP router 198.51.100.1":"Маршрутизатор провайдера 198.51.100.1","expires at the second router":"гине на другому маршрутизаторі","type 11 · from 198.51.100.1":"тип 11 · від 198.51.100.1","That’s Traceroute":"Це і є traceroute","TTL 1, 2, 3 … until it arrives":"TTL 1, 2, 3 … доки не дійде","tracert automates this: it raises the TTL by one each time, sends three probes per hop and lists who reports back. Hops 3 to 12 work the same way, and with TTL 13 the request finally reaches the server, which replies normally.":"tracert автоматизує це: щоразу збільшує TTL на одиницю, надсилає по три проби на хоп і показує, хто відповідає. Хопи з 3 до 12 працюють так само, а з TTL 13 запит нарешті доходить до сервера, який відповідає як завжди.","12 routers, then the server":"12 маршрутизаторів, потім сервер","Per hop":"На хоп","3 probes":"3 проби","On Linux":"У Linux","traceroute sends UDP":"traceroute надсилає UDP","enough hops to arrive":"досить хопів, щоб дійти","the server itself answers":"відповідає сам сервер","end of the route":"кінець маршруту",Unreachable:"Недосяжно","Nothing listening on that port":"На тому порту ніхто не слухає","An app sends a UDP datagram to port 9999, where nothing is listening. The server can’t deliver it, so it replies with Destination Unreachable, code 3 (port unreachable), quoting the start of the datagram. Many firewalls drop such packets silently instead.":"Застосунок надсилає UDP-датаграму на порт 9999, де ніхто не слухає. Сервер не може її доставити, тож відповідає Destination Unreachable, код 3 (порт недосяжний), цитуючи початок датаграми. Багато брандмауерів натомість мовчки відкидають такі пакети.","3, 3 (port unreachable)":"3, 3 (порт недосяжний)","Other codes":"Інші коди","0 net, 1 host, 4 too big":"0 мережа, 1 хост, 4 завеликий",Firewalls:"Брандмауери","Often silent instead":"Часто натомість мовчать","to port 9999":"на порт 9999","nothing listening there":"там ніхто не слухає","type 3 · code 3":"тип 3 · код 3","port unreachable":"порт недосяжний","ICMP · Echo request":"ICMP · Ехо-запит",Code:"Код","Covers the whole ICMP message.":"Охоплює все повідомлення ICMP.",Identifier:"Ідентифікатор","Matches replies to this ping program.":"Зіставляє відповіді з цією програмою ping.","Windows counts up across every ping it sends.":"Windows рахує наскрізь через усі ping, які надсилає.","Windows ping’s filler: the alphabet, a to w, then again.":"Заповнювач ping у Windows: абетка від a до w, а потім знову.","ICMP · Echo reply":"ICMP · Ехо-відповідь","Sent back exactly as it came.":"Надсилається назад точно таким, яким прийшов.","ICMP · Time exceeded (TTL reached 0)":"ICMP · Час вичерпано (TTL дійшов до 0)","Time exceeded (TTL reached 0)":"Час вичерпано (TTL дійшов до 0)",Unused:"Не використовується","Original packet":"Початковий пакет","Its source, destination":"Його джерело, призначення","its IP header and first 8 bytes (28 bytes)":"його заголовок IP і перші 8 байтів (28 байтів)","App data":"Дані застосунку","What the app sent; nothing on the server is listening for it.":"Те, що надіслав застосунок; на сервері ніхто цього не слухає.","ICMP · Destination unreachable (port unreachable)":"ICMP · Призначення недосяжне (порт недосяжний)","Destination unreachable (port unreachable)":"Призначення недосяжне (порт недосяжний)","Sending Email":"Надсилання пошти","SMTP command":"Команда SMTP","SMTP reply":"Відповідь SMTP","SMTP moves email: from your mail app to your provider’s server, and from that server to the recipient’s. It is a conversation of short text commands, each answered with a three-digit reply code. Reading mail is a different job, done with IMAP or POP3.":"SMTP переносить пошту: з вашого поштового застосунку на сервер провайдера, а з того сервера — на сервер одержувача. Це розмова з коротких текстових команд, на кожну з яких приходить тризначний код відповіді. Читання пошти — інша робота, її виконують IMAP або POP3.","465/587 submit, 25 relay":"465/587 відправлення, 25 ретрансляція","TCP, usually with TLS":"TCP, зазвичай з TLS",Commands:"Команди",Replies:"Відповіді","2xx ok, 3xx go on, 4/5xx error":"2xx гаразд, 3xx далі, 4/5xx помилка","Mail delivered":"Лист доставлено","Two hops, one message":"Два переходи, один лист","Alice’s app handed the message to her provider over an encrypted, logged-in connection. The provider found Bob’s mail server in DNS and relayed it there, upgrading that link to TLS. It now waits in Bob’s mailbox until he reads it with IMAP or POP3.":"Застосунок Аліси передав лист її провайдерові зашифрованим з’єднанням із входом. Провайдер знайшов поштовий сервер Боба в DNS і ретранслював лист туди, перевівши це з’єднання на TLS. Тепер лист чекає в скриньці Боба, доки той не прочитає його через IMAP або POP3.","Laptop → provider → Bob’s":"Ноутбук → провайдер → сервер Боба",Submission:"Відправлення","Port 465, TLS, login":"Порт 465, TLS, вхід",Relay:"Ретрансляція","Port 25, STARTTLS":"Порт 25, STARTTLS","Checks at Bob’s":"Перевірки в Боба","Connect Securely":"Захищений зв’язок","Alice presses Send. Her mail app connects to her provider’s submission server, smtp.example.com, on port 465. On this port TLS starts immediately, so the whole SMTP conversation, including her password, is encrypted.":"Аліса натискає «Надіслати». Її поштовий застосунок під’єднується до сервера відправлення провайдера, smtp.example.com, на порту 465. На цьому порту TLS починається одразу, тож уся розмова SMTP, зокрема її пароль, зашифрована.","TLS from the start":"TLS від самого початку","SMTP inside TLS":"SMTP усередині TLS","Greeting & Login":"Привітання і вхід","EHLO, then AUTH":"EHLO, потім AUTH","The server greets with code 220. The app says EHLO and the server lists what it supports, including AUTH. The app logs in with AUTH PLAIN (user name and password, base64-encoded) and gets 235: authenticated.":"Сервер вітається кодом 220. Застосунок каже EHLO, і сервер перелічує, що підтримує, зокрема AUTH. Застосунок входить через AUTH PLAIN (ім’я користувача й пароль у base64) і отримує 235: автентифіковано.",Greeting:"Привітання",Capabilities:"Можливості","Login result":"Результат входу","user and password, base64":"користувач і пароль, base64","Send the Message":"Надсилання листа","Envelope, then content":"Конверт, потім уміст","MAIL FROM and RCPT TO are the envelope: sender and recipient. PIPELINING lets all three commands share one packet. After 354 comes the message, ended by a line holding just a dot.":"MAIL FROM і RCPT TO — це конверт: відправник і одержувач. PIPELINING дає змогу всім трьом командам поміститися в один пакет. Після 354 іде сам лист, який закінчується рядком, де стоїть лише крапка.",Envelope:"Конверт","Content ends":"Кінець умісту","A line with only “.”":"Рядок лише з «.»",Result:"Результат","… message …":"… лист …","Find Bob’s Server":"Де сервер Боба?","An MX lookup in DNS":"Пошук MX у DNS","Alice’s provider now has to deliver to example.org. It asks DNS for that domain’s MX record, which names the server that accepts its mail, then looks up that server’s address.":"Тепер провайдер Аліси має доставити лист на example.org. Він запитує в DNS запис MX цього домену, де вказано сервер, що приймає його пошту, а потім шукає адресу цього сервера.","MX record":"Запис MX","Asked by":"Запитує","Alice’s provider":"Провайдер Аліси","Server to Server":"Між серверами","Port 25, upgraded with STARTTLS":"Порт 25, перехід на STARTTLS","The provider connects to mx.example.org on port 25. This conversation starts in plain text: the greeting and EHLO reply advertise STARTTLS, the provider asks for it, gets 220 and both sides switch to TLS.":"Провайдер під’єднується до mx.example.org на порту 25. Ця розмова починається відкритим текстом: привітання й відповідь на EHLO оголошують STARTTLS, провайдер просить його, отримує 220, і обидві сторони переходять на TLS.","Starts as":"Починається як","Plain text":"Відкритий текст",Upgrade:"Перехід",Deliver:"Доставлення","The same transaction again":"Та сама транзакція ще раз","With TLS on, the provider repeats EHLO, then the envelope and the message, now with a DKIM signature and a Received header added. Bob’s server checks SPF, DKIM and DMARC and accepts it.":"Увімкнувши TLS, провайдер повторює EHLO, потім конверт і лист, тепер із доданими підписом DKIM і заголовком Received. Сервер Боба перевіряє SPF, DKIM і DMARC і приймає лист.","Login needed":"Потрібен вхід","No (server to server)":"Ні (між серверами)","1,316 bytes (signed)":"1,316 байтів (з підписом)","Server Hello + encrypted handshake, 2 segments":"Server Hello + зашифроване рукостискання, 2 сегменти","250 capabilities (PIPELINING, SIZE, AUTH …)":"250 можливості (PIPELINING, SIZE, AUTH …)","AUTH PLAIN (credentials)":"AUTH PLAIN (облікові дані)","MAIL FROM, RCPT TO, DATA (pipelined)":"MAIL FROM, RCPT TO, DATA (конвеєром)","Message (316 bytes), then “.”":"Лист (316 байтів), потім «.»","250 capabilities (PIPELINING, STARTTLS …)":"250 можливості (PIPELINING, STARTTLS …)","250 capabilities (PIPELINING, SIZE …)":"250 можливості (PIPELINING, SIZE …)","Message (1,316 bytes), then “.”":"Лист (1,316 байтів), потім «.»","What this client supports. Its exact contents vary from client to client; this is an example.":"Що підтримує цей клієнт. Точний уміст залежить від клієнта; це приклад.","up to 512 bytes":"до 512 байтів","The server’s choices and its key share.":"Вибір сервера і його частка ключа.","Encrypted Extensions, Certificate (the chain), Certificate Verify (the signature), Finished":"Encrypted Extensions, Certificate (ланцюжок), Certificate Verify (підпис), Finished","Alice’s message (316 bytes), then a line holding only “.”":"Лист Аліси (316 байтів), потім рядок, де лише «.»","example.org, type MX, class IN":"example.org, тип MX, клас IN","mx.example.org, type A, class IN":"mx.example.org, тип A, клас IN",Timestamps:"Мітки часу","Used to measure round trips; both sides offered them.":"Використовуються для вимірювання часу туди й назад; обидві сторони їх запропонували.","The signed message (1,316 bytes), then a line holding only “.”":"Підписаний лист (1,316 байтів), потім рядок, де лише «.»","Downloading Email":"Завантаження пошти","POP3 command":"Команда POP3","POP3 reply":"Відповідь POP3","Post Office Protocol, version 3":"Post Office Protocol, версія 3","POP3 lets a mail app download messages from a mailbox on a server. It was designed for one device that fetches mail and then removes it from the server. Commands are short words, and every reply starts with +OK or -ERR.":"POP3 дає поштовому застосунку змогу завантажувати листи зі скриньки на сервері. Його створено для одного пристрою, який забирає пошту, а потім видаляє її з сервера. Команди — короткі слова, і кожна відповідь починається з +OK або -ERR.",Model:"Модель","Download, then delete":"Завантажити, потім видалити","Mail downloaded":"Пошту завантажено","And gone from the server":"І з сервера її вже немає","Bob’s app logged in, saw two messages, downloaded the first and deleted it, which the server carried out at QUIT. That message now lives only on this laptop, which is why POP3 suits one device and IMAP suits several.":"Застосунок Боба увійшов, побачив два листи, завантажив перший і видалив його, що сервер виконав під час QUIT. Тепер цей лист є лише на цьому ноутбуці, тому POP3 підходить для одного пристрою, а IMAP — для кількох.","2 waiting, 1 downloaded":"2 чекають, 1 завантажено",Deleted:"Видалено","At QUIT (UPDATE state)":"Під час QUIT (стан UPDATE)","Best for":"Найкраще для","A single device":"Одного пристрою","Bob’s mail app connects to pop.example.org on port 995, where TLS starts right away. Inside it, the server greets with +OK. (On port 110 the session starts in plain text and is upgraded with the STLS command.)":"Поштовий застосунок Боба під’єднується до pop.example.org на порту 995, де TLS починається одразу. Усередині сервер вітається відповіддю +OK. (На порту 110 сеанс починається відкритим текстом і переходить на TLS командою STLS.)","USER, then PASS":"USER, потім PASS","The app sends the user name with USER and the password with PASS. Each command gets its own +OK. Because the session is inside TLS, the password isn’t readable on the way.":"Застосунок надсилає ім’я користувача командою USER, а пароль — командою PASS. Кожна команда отримує власне +OK. Оскільки сеанс іде всередині TLS, пароль дорогою не прочитати.","Protected by":"Захищено","Check the Mailbox":"Огляд скриньки","STAT and LIST":"STAT і LIST","STAT returns the number of messages and their total size: 2 messages, 5120 bytes. LIST gives each message’s number and size, ending with a line holding just a dot.":"STAT повертає кількість листів і їхній загальний розмір: 2 листи, 5120 байтів. LIST дає номер і розмір кожного листа й закінчується рядком, де стоїть лише крапка.","Message 1":"Лист 1","Message 2":"Лист 2",Download:"Завантаження","RETR 1 asks for the first message. The server answers +OK with its size, then the message and a closing dot: 1904 bytes plus the reply line, two TCP segments.":"RETR 1 запитує перший лист. Сервер відповідає +OK з його розміром, потім надсилає лист і завершальну крапку: 1904 байти плюс рядок відповіді, два TCP-сегменти.",Command:"Команда","Delete & Quit":"Видалення і вихід","Deleted only at QUIT":"Видаляється лише під час QUIT","DELE 1 only marks the message. The server removes it when the app says QUIT: if the connection dropped before that, nothing would be deleted. Many apps offer “leave a copy on the server”, which skips DELE.":"DELE 1 лише позначає лист. Сервер видаляє його, коли застосунок каже QUIT: якби з’єднання обірвалося раніше, нічого не було б видалено. Багато застосунків пропонують «залишати копію на сервері», і тоді DELE не надсилається.","Marks message 1":"Позначає лист 1",Removed:"Видалено",Option:"Параметр","Leave a copy on server":"Залишати копію на сервері","PASS (password)":"PASS (пароль)","+OK 1904 octets, message, “.” (2 segments)":"+OK 1904 octets, лист, «.» (2 сегменти)","+OK 1904 octets, the 1,904-byte message, then a line holding only “.”":"+OK 1904 octets, лист на 1,904 байти, потім рядок, де лише «.»","Mail That Stays in Sync":"Пошта, що лишається синхронною","IMAP command":"Команда IMAP","IMAP response":"Відповідь IMAP","Internet Message Access Protocol":"Протокол доступу до інтернет-повідомлень","IMAP lets mail apps work with a mailbox that stays on the server. Folders, read and flagged marks and deletions are kept there, so a phone, a laptop and webmail all see the same mailbox. The server can also tell an app about new mail as it arrives.":"IMAP дає поштовим застосункам змогу працювати зі скринькою, що лишається на сервері. Папки, позначки «прочитано» і «важливе» та видалення зберігаються там, тож телефон, ноутбук і вебпошта бачать ту саму скриньку. Сервер також може повідомити застосунок про нову пошту, щойно вона надійде.","Mail stays on the server":"Пошта лишається на сервері",Syncs:"Синхронізує","Folders and flags":"Папки й прапорці","Mailbox in sync":"Скринька синхронізована","Read once, read everywhere":"Прочитали раз — прочитано всюди","Bob’s app opened his inbox, read a message, which marked it \\Seen on the server for all his devices, and then waited with IDLE until the server announced new mail. Nothing was deleted: the server still holds everything.":"Застосунок Боба відкрив його вхідні, прочитав лист, що позначило його як \\Seen на сервері для всіх пристроїв Боба, а потім чекав через IDLE, доки сервер не повідомив про нову пошту. Нічого не видалено: на сервері досі все є.","2, then 3 (new mail)":"2, потім 3 (нова пошта)","Read mark":"Позначка «прочитано»","\\Seen, stored on server":"\\Seen, зберігається на сервері","New mail":"Нова пошта","Pushed during IDLE":"Надіслано під час IDLE","Bob’s app connects to imap.example.org on port 993, where TLS starts right away. The server greets with an untagged “* OK” line that also lists its capabilities, such as IDLE.":"Застосунок Боба під’єднується до imap.example.org на порту 993, де TLS починається одразу. Сервер вітається рядком «* OK» без тегу, який також перелічує його можливості, як-от IDLE.","Commands carry tags":"Команди мають теги","Every command starts with a tag the app chooses, like a1, and the server ends its answer with the same tag. That way several commands can be in flight and each reply is matched up. Lines starting with * are untagged data.":"Кожна команда починається з тегу, який вибирає застосунок, наприклад a1, і сервер завершує відповідь тим самим тегом. Так кілька команд можуть бути в дорозі одночасно, і кожна відповідь зіставляється зі своєю. Рядки, що починаються з *, — це дані без тегу.",Tags:"Теги","Match replies to commands":"Зіставляють відповіді з командами","Open the Inbox":"Відкриття вхідних","SELECT a folder":"SELECT папки","SELECT INBOX opens the folder. The server reports the message count, the flags it supports and the first unread message, then confirms the folder is open read-write.":"SELECT INBOX відкриває папку. Сервер повідомляє кількість листів, підтримувані прапорці й перший непрочитаний лист, а потім підтверджує, що папку відкрито для читання й запису.","First unread":"Перший непрочитаний",Access:"Доступ","Read a Message":"Читання листа","FETCH, and the \\Seen flag":"FETCH і прапорець \\Seen","FETCH 2 BODY[] downloads message 2 (three TCP segments). That sets its \\Seen flag on the server, so it shows as read on Bob’s phone too, and the message stays there.":"FETCH 2 BODY[] завантажує лист 2 (три TCP-сегменти). Це встановлює його прапорець \\Seen на сервері, тож лист показується прочитаним і на телефоні Боба, а сам лишається там.","Flag set":"Встановлено прапорець","\\Seen (on the server)":"\\Seen (на сервері)","Wait for New Mail":"Чекання на пошту","IDLE: the server pushes":"IDLE: сервер сам надсилає","IDLE tells the server “let me know when something changes”. About 42 seconds later Alice’s message arrives and the server pushes “* 3 EXISTS” straight away. The app ends IDLE with DONE and can fetch the new mail.":"IDLE каже серверу: «повідом мене, коли щось зміниться». Приблизно через 42 секунди надходить лист Аліси, і сервер одразу надсилає «* 3 EXISTS». Застосунок завершує IDLE командою DONE і може завантажити нову пошту.","Server says":"Сервер каже","* 3 EXISTS (new mail)":"* 3 EXISTS (нова пошта)","Ended by":"Завершується","a1 LOGIN (user and password)":"a1 LOGIN (користувач і пароль)","* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, the 3,216-byte message, then a3 OK FETCH completed":"* 2 FETCH (FLAGS (\\Seen) BODY[] {3216}, лист на 3,216 байтів, потім a3 OK FETCH completed","Transferring Files":"Передача файлів","FTP command":"Команда FTP","FTP reply":"Відповідь FTP","File data":"Дані файлу","FTP moves files between a client and a server. It is unusual in using two TCP connections: one for commands and replies, and a fresh one for each file or listing. It dates from the early 1970s and sends everything, passwords included, as plain text.":"FTP переносить файли між клієнтом і сервером. Незвичайне в ньому те, що він використовує два TCP-з’єднання: одне для команд і відповідей і нове для кожного файлу чи списку. Він походить із початку 1970-х і надсилає все, зокрема паролі, відкритим текстом.","21 control, data varies":"21 керування, дані різні",Connections:"З’єднання","Control + one per transfer":"Керування + одне на передачу",Encryption:"Шифрування","None (plain text)":"Немає (відкритий текст)","Safer options":"Безпечніші варіанти","File downloaded":"Файл завантажено","Two connections, no encryption":"Два з’єднання, без шифрування","Commands went over the control connection, the file over its own data connection, and closing that connection marked the end of the file. Anyone on the path could have read the password and the file, which is why SFTP or FTPS is used today.":"Команди йшли керувальним з’єднанням, файл — власним з’єднанням даних, а закриття цього з’єднання позначило кінець файлу. Будь-хто на шляху міг прочитати і пароль, і файл, тому сьогодні використовують SFTP або FTPS.","2 (control + data)":"2 (керування + дані)",File:"Файл","4,000 bytes, 3 segments":"4,000 байтів, 3 сегменти",Password:"Пароль","Sent in plain text":"Надсилається відкритим текстом","Use instead":"Краще використовувати","Control Connection":"Канал керування","Port 21, plain text":"Порт 21, відкритий текст","The FTP app opens a TCP connection to ftp.example.com on port 21. This control connection carries commands and replies for the whole session. The server greets with 220. Like SMTP, every reply starts with a three-digit code.":"FTP-застосунок відкриває TCP-з’єднання з ftp.example.com на порту 21. Це керувальне з’єднання несе команди й відповіді впродовж усього сеансу. Сервер вітається кодом 220. Як і в SMTP, кожна відповідь починається з тризначного коду.","USER and PASS, readable by anyone":"USER і PASS, які може прочитати будь-хто","The app sends USER, the server asks for the password with 331, and PASS sends it. Nothing is encrypted, so the user name and password cross every network on the way as readable text.":"Застосунок надсилає USER, сервер просить пароль кодом 331, а PASS надсилає його. Нічого не зашифровано, тож ім’я користувача й пароль проходять кожну мережу на шляху читабельним текстом.","Visible to":"Видно","Anyone on the path":"Будь-кому на шляху","Passive Mode":"Пасивний режим","The server names a data port":"Сервер називає порт даних","TYPE I asks for a byte-for-byte binary copy. PASV asks the server to open a port for the data connection. The reply encodes the address and port as six numbers: 195 × 256 + 149 = port 50069. The laptop connects out, which works through NAT.":"TYPE I просить двійкову копію байт у байт. PASV просить сервер відкрити порт для з’єднання даних. Відповідь кодує адресу й порт шістьма числами: 195 × 256 + 149 = порт 50069. Ноутбук під’єднується назовні сам, і це працює через NAT.","Data port":"Порт даних","Active mode":"Активний режим","Server dials in: NAT blocks":"Сервер дзвонить усередину: NAT блокує","Data Connection":"З’єднання даних","A second TCP connection":"Друге TCP-з’єднання","The app opens a second TCP connection, to port 50069, and asks for the file on the control connection with RETR. The server answers 150 there and starts sending the file over the new connection.":"Застосунок відкриває друге TCP-з’єднання, з портом 50069, і запитує файл керувальним з’єднанням командою RETR. Сервер відповідає там кодом 150 і починає надсилати файл новим з’єднанням.","Data to":"Дані на","The File Arrives":"Файл надходить","Closing the connection ends it":"Закриття з’єднання завершує його","The 4,000 bytes arrive in 3 TCP segments. FTP sends no length marker in the data itself: the server closes the data connection to mark the end of the file. Once the laptop has acknowledged everything, the server confirms with 226 on the control connection.":"4,000 байтів надходять у 3 TCP-сегментах. FTP не надсилає в самих даних жодної позначки довжини: сервер закриває з’єднання даних, щоб позначити кінець файлу. Коли ноутбук підтвердив усе, сервер підтверджує кодом 226 керувальним з’єднанням.","End of file":"Кінець файлу","Data connection closed":"З’єднання даних закрито","4,000 bytes, readable by anyone":"4,000 байтів, які може прочитати будь-хто","end of file:":"кінець файлу:","data connection closed":"з’єднання даних закрито",Quit:"Вихід","Close the control connection":"Закриття керувального з’єднання","QUIT ends the session and the server says goodbye with 221. For anything sensitive, SFTP (a different protocol, run over SSH) or FTPS (FTP inside TLS) gives the same job encryption.":"QUIT завершує сеанс, і сервер прощається кодом 221. Для будь-чого чутливого SFTP (інший протокол, що працює поверх SSH) або FTPS (FTP усередині TLS) виконують ту саму роботу із шифруванням.","Encrypted cousins":"Зашифровані родичі","FTP data":"Дані FTP","The file itself, unencrypted: anyone on the path could read it.":"Сам файл, незашифрований: будь-хто на шляху міг би його прочитати.","Secure Remote Login":"Захищений віддалений вхід","Plain setup":"Відкрите налаштування","From laptop":"Від ноутбука","From server":"Від сервера","Some packets not shown":"Деякі пакети не показано","SSH gives you an encrypted, authenticated connection to another computer, to run commands on it, copy files (SFTP, scp) or carry other connections. The server proves who it is with a host key; you prove who you are with a key pair or a password.":"SSH дає зашифроване, автентифіковане з’єднання з іншим комп’ютером, щоб виконувати на ньому команди, копіювати файли (SFTP, scp) або передавати інші з’єднання. Сервер доводить, хто він, ключем хоста; ви доводите, хто ви, парою ключів або паролем.","Server proves":"Сервер доводить","Host key (known_hosts)":"Ключ хоста (known_hosts)","You prove":"Ви доводите","Key pair or password":"Пара ключів або пароль","Logged in securely":"Безпечний вхід виконано","Encrypted from the key exchange on":"Зашифровано від обміну ключами","The two sides agreed on algorithms, built shared keys with a post-quantum hybrid exchange, and the server proved its identity with its host key. Alice proved hers by signing with a private key that never left the laptop, then typed a command, one packet per key.":"Сторони узгодили алгоритми, створили спільні ключі постквантовим гібридним обміном, і сервер довів свою особу ключем хоста. Аліса довела свою, підписавши приватним ключем, який ніколи не залишав ноутбука, а потім ввела команду, по пакету на клавішу.",Login:"Вхід у систему","Ed25519 key, no password":"Ключ Ed25519, без пароля","Say Hello":"Привітання","Versions, in plain text":"Версії, відкритим текстом","Alice runs “ssh alice@server.example.com”. After the TCP handshake on port 22, each side sends one line of plain text naming the SSH protocol version (2.0) and its software. Everything else in SSH is binary.":"Аліса запускає «ssh alice@server.example.com». Після TCP-рукостискання на порту 22 кожна сторона надсилає один рядок відкритого тексту з версією протоколу SSH (2.0) і своїм програмним забезпеченням. Усе інше в SSH — двійкове.","Agree on Algorithms":"Вибір алгоритмів","KEXINIT lists, first match wins":"Списки KEXINIT, перший збіг перемагає","Each side sends a KEXINIT listing every algorithm it supports, in order of preference, for key exchange, host keys, encryption, integrity and compression. In each category the first algorithm on the laptop’s list that the server also supports is chosen.":"Кожна сторона надсилає KEXINIT зі списком усіх підтримуваних алгоритмів у порядку переваги: для обміну ключами, ключів хоста, шифрування, цілісності й стиснення. У кожній категорії вибирається перший алгоритм зі списку ноутбука, який підтримує й сервер.","Host key":"Ключ хоста","server’s algorithm lists":"списки алгоритмів сервера","in order of preference":"у порядку переваги","laptop’s algorithm lists":"списки алгоритмів ноутбука","Key Exchange":"Обмін ключами","Shared keys, and a host key check":"Спільні ключі й перевірка ключа хоста","The laptop sends its half of a hybrid exchange: a Streamlined NTRU Prime key, chosen to resist future quantum computers, plus an X25519 key. The server answers with its half, its host key and a signature over the exchange. NEWKEYS switches encryption on.":"Ноутбук надсилає свою половину гібридного обміну: ключ Streamlined NTRU Prime, вибраний для стійкості до майбутніх квантових комп’ютерів, плюс ключ X25519. Сервер відповідає своєю половиною, ключем хоста й підписом над обміном. NEWKEYS вмикає шифрування.",Hybrid:"Гібрид","Matches known_hosts":"Збігається з known_hosts","First visit":"Перший візит","ssh asks you to confirm":"ssh просить підтвердити","public keys":"публічні ключі","its half, its host key":"його половина, ключ хоста","and a signature":"і підпис","Log In with a Key":"Вхід за ключем","Sign, don’t send a secret":"Підписати, а не надіслати секрет","The server lists the login methods it accepts. The laptop offers Alice’s public key, and the server says it would accept it. The laptop then signs this session with the private key, which never leaves the laptop. The server checks the signature against authorized_keys.":"Сервер перелічує методи входу, які приймає. Ноутбук пропонує публічний ключ Аліси, і сервер каже, що прийняв би його. Потім ноутбук підписує цей сеанс приватним ключем, який ніколи не залишає ноутбука. Сервер перевіряє підпис за authorized_keys.",Methods:"Методи","Ed25519, private stays here":"Ed25519, приватний лишається тут","Checked with":"Перевіряється за","alice’s public key":"публічний ключ alice","would you accept it?":"приймете його?","yes, that key":"так, цей ключ","is in authorized_keys":"є в authorized_keys","same key, plus a signature":"той самий ключ плюс підпис","made with the private key":"зроблений приватним ключем","logged in":"вхід виконано","Open a Session":"Відкриття сеансу","Channels inside one connection":"Канали в одному з’єднанні","One SSH connection can carry many channels: a shell, file transfers, forwarded ports. The laptop opens a session channel, then asks for a terminal and a shell (not shown), and the server sends its welcome text and a prompt.":"Одне SSH-з’єднання може нести багато каналів: оболонку, передачу файлів, переспрямовані порти. Ноутбук відкриває канал сеансу, потім просить термінал і оболонку (не показано), і сервер надсилає вітальний текст і запрошення.",Channel:"Канал",session:"session","Then asks for":"Потім просить","A terminal and a shell":"Термінал і оболонку","Also possible":"Також можливо","SFTP, port forwarding":"SFTP, переспрямування портів","open a channel:":"відкрити канал:","channel open":"канал відкрито","Type a Command":"Введення команди","Every key is a packet":"Кожна клавіша — пакет","Alice types pwd. Each key goes out at once in its own encrypted packet, and the server sends the character back to be shown (the echo). Since 9.5, OpenSSH sends keys on a 20 ms beat and adds decoy packets, so typing rhythm is harder to read from the timing.":"Аліса вводить pwd. Кожна клавіша вирушає одразу у власному зашифрованому пакеті, а сервер надсилає символ назад, щоб його показати (ехо). Починаючи з 9.5, OpenSSH надсилає клавіші в ритмі 20 ms і додає пакети-приманки, тож ритм друку важче вгадати за часом.","Per key":"На клавішу","1 packet, 90 bytes":"1 пакет, 90 байтів",Echo:"Ехо","Sent back by the server":"Надсилає назад сервер",Timing:"Час","20 ms beat plus decoys":"Ритм 20 ms плюс приманки","Enter key":"Клавіша Enter","Client: KEX_ECDH_INIT (sntrup761x25519 public keys)":"Клієнт: KEX_ECDH_INIT (публічні ключі sntrup761x25519)","Server: KEX_ECDH_REPLY (host key, its half, signature)":"Сервер: KEX_ECDH_REPLY (ключ хоста, його половина, підпис)","Encrypted (len=44): service request, ssh-userauth":"Зашифровано (len=44): запит служби, ssh-userauth","Encrypted (len=44): service accept":"Зашифровано (len=44): службу прийнято","Encrypted (len=68): login with method none":"Зашифровано (len=68): вхід методом none","Encrypted (len=52): try publickey,password":"Зашифровано (len=52): спробуйте publickey,password","Encrypted (len=140): offer public key":"Зашифровано (len=140): пропозиція публічного ключа","Encrypted (len=100): public key OK":"Зашифровано (len=100): публічний ключ OK","Encrypted (len=308): public key + signature":"Зашифровано (len=308): публічний ключ + підпис","Encrypted (len=28): login success":"Зашифровано (len=28): вхід успішний","Encrypted (len=52): channel open: session":"Зашифровано (len=52): відкриття каналу: session","Encrypted (len=44): channel open confirmed":"Зашифровано (len=44): відкриття каналу підтверджено","Encrypted (len=36): keystroke":"Зашифровано (len=36): натискання клавіші","Encrypted (len=36): echo":"Зашифровано (len=36): ехо","Encrypted (len=36): keystroke (Enter)":"Зашифровано (len=36): натискання клавіші (Enter)","Encrypted (len=132): output and a new prompt":"Зашифровано (len=132): вивід і нове запрошення","Packet length":"Довжина пакета","Bytes after this field.":"Байти після цього поля.","Padding length":"Довжина доповнення","Random padding brings the packet to a multiple of 8 bytes.":"Випадкове доповнення робить розмір пакета кратним 8 байтам.",Cookie:"Cookie","Host keys":"Ключі хоста","Ciphers, out":"Шифри, вихідні","Ciphers, in":"Шифри, вхідні","MACs, out":"MAC, вихідні","Compression, out":"Стиснення, вихідні","Compression, in":"Стиснення, вхідні","Languages, out":"Мови, вихідні","Languages, in":"Мови, вхідні","First packet follows":"Далі йде перший пакет",Reserved:"Зарезервовано","Public keys":"Публічні ключі","51 bytes: ssh-ed25519 public key":"51 байт: публічний ключ ssh-ed25519","Server’s half":"Половина сервера","1071 bytes (sntrup761 ciphertext 1,039 + X25519 32)":"1071 байт (шифротекст sntrup761 1,039 + X25519 32)",Signature:"Підпис","83 bytes: ssh-ed25519 signature over the exchange":"83 байти: підпис ssh-ed25519 над обміном","From the next packet on, this side encrypts.":"Починаючи з наступного пакета, ця сторона шифрує.","SSH · encrypted packet":"SSH · зашифрований пакет","Encrypted packet":"Зашифрований пакет","With chacha20-poly1305 even the length is encrypted; a 16-byte tag at the end shows any change.":"З chacha20-poly1305 зашифровано навіть довжину; 16-байтовий тег у кінці виявляє будь-яку зміну.","SSH_MSG_USERAUTH_REQUEST (50): user “alice”, service “ssh-connection”, method “none”":"SSH_MSG_USERAUTH_REQUEST (50): користувач «alice», служба «ssh-connection», метод «none»","SSH_MSG_USERAUTH_FAILURE (51): methods that can continue: “publickey,password”":"SSH_MSG_USERAUTH_FAILURE (51): методи, якими можна продовжити: «publickey,password»","SSH_MSG_USERAUTH_REQUEST (50): method “publickey”, no signature, the ssh-ed25519 public key":"SSH_MSG_USERAUTH_REQUEST (50): метод «publickey», без підпису, публічний ключ ssh-ed25519","SSH_MSG_USERAUTH_PK_OK (60): the same ssh-ed25519 key":"SSH_MSG_USERAUTH_PK_OK (60): той самий ключ ssh-ed25519","SSH_MSG_USERAUTH_REQUEST (50): method “publickey-hostbound-v00@openssh.com”, the key, the server’s host key and a signature":"SSH_MSG_USERAUTH_REQUEST (50): метод «publickey-hostbound-v00@openssh.com», ключ, ключ хоста сервера й підпис","SSH_MSG_CHANNEL_OPEN (90): “session”, channel 0, window 2 MB, packets up to 32 KB":"SSH_MSG_CHANNEL_OPEN (90): «session», канал 0, вікно 2 MB, пакети до 32 KB","SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): channel 0 is open":"SSH_MSG_CHANNEL_OPEN_CONFIRMATION (91): канал 0 відкрито","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”":"SSH_MSG_CHANNEL_DATA (94), канал 0: 1 байт, «p»","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “p”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), канал 0: 1 байт, «p», надіслано назад для показу","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”":"SSH_MSG_CHANNEL_DATA (94), канал 0: 1 байт, «w»","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “w”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), канал 0: 1 байт, «w», надіслано назад для показу","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”":"SSH_MSG_CHANNEL_DATA (94), канал 0: 1 байт, «d»","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, “d”, sent back to be shown":"SSH_MSG_CHANNEL_DATA (94), канал 0: 1 байт, «d», надіслано назад для показу","SSH_MSG_CHANNEL_DATA (94), channel 0: 1 byte, a carriage return (Enter)":"SSH_MSG_CHANNEL_DATA (94), канал 0: 1 байт, повернення каретки (Enter)","SSH_MSG_CHANNEL_DATA (94), channel 0: 94 bytes: a new line, the shell’s terminal codes, “/home/alice”, and the coloured prompt":"SSH_MSG_CHANNEL_DATA (94), канал 0: 94 байти: новий рядок, коди терміналу оболонки, «/home/alice» і кольорове запрошення","Encryption Explained":"Шифрування простими словами","From browser":"Від браузера","TLS puts a secure channel on top of TCP. It proves the server’s identity with a certificate, agrees on fresh keys, then encrypts and authenticates everything sent. HTTPS, secure email and many other protocols run inside it. SSL was the name of its predecessor.":"TLS створює захищений канал поверх TCP. Він доводить особу сервера сертифікатом, узгоджує нові ключі, а потім шифрує й автентифікує все, що надсилається. HTTPS, захищена пошта й багато інших протоколів працюють усередині нього. SSL — назва його попередника.",Sits:"Розташування","Between TCP and the app":"Між TCP і застосунком","OSI layer":"Рівень OSI","Often placed at 6":"Часто відносять до 6",Current:"Актуальна",Retired:"Застарілі","SSL 2 and 3, TLS 1.0 and 1.1":"SSL 2 і 3, TLS 1.0 і 1.1","The app’s own (443, 993 …)":"Порт застосунку (443, 993 …)","Secure from start to finish":"Захищено від початку до кінця","One round trip to set up":"Один обмін туди-назад на налаштування","One round trip agreed on a version, a cipher and a post-quantum hybrid key. The certificate chain proved who the server was, and every byte after the Server Hello was encrypted and authenticated, right up to the close_notify. Press REPLAY to watch it again.":"Один обмін туди-назад узгодив версію, шифр і постквантовий гібридний ключ. Ланцюжок сертифікатів довів, хто такий сервер, а кожен байт після Server Hello був зашифрований і автентифікований, аж до close_notify. Натисніть ЗНОВУ, щоб переглянути ще раз.","1 round trip":"1 обмін туди-назад","Everything the browser supports":"Усе, що підтримує браузер","After the TCP handshake the browser lists what it can do: TLS versions, cipher suites, and key shares for the groups it expects, including the post-quantum hybrid X25519MLKEM768. It also names the site (SNI) and the protocols it speaks (ALPN).":"Після TCP-рукостискання браузер перелічує, що вміє: версії TLS, набори шифрів і частки ключа для груп, яких очікує, зокрема постквантового гібрида X25519MLKEM768. Він також називає сайт (SNI) і протоколи, якими розмовляє (ALPN).",Versions:"Версії","versions, ciphers, key shares":"версії, шифри, частки ключа","Choices made, keys computed":"Вибір зроблено, ключі обчислено","The server picks TLS 1.3, the cipher suite and the hybrid group, and sends its own key share. From the two shares both sides compute the same secret without it ever crossing the network. Everything after this message is encrypted.":"Сервер вибирає TLS 1.3, набір шифрів і гібридну групу та надсилає свою частку ключа. З двох часток обидві сторони обчислюють той самий секрет, і він ніколи не проходить мережею. Усе після цього повідомлення зашифровано.",Group:"Група","From here on":"Відтепер","its key share":"його частка ключа",Certificate:"Сертифікат","Who the server is, proven":"Хто такий сервер, доведено","Now encrypted, the flight continues: the chosen protocol (http/1.1), the certificate chain, a signature made with the certificate’s private key, and Finished.":"Уже зашифровано пакет продовжується: вибраний протокол (http/1.1), ланцюжок сертифікатів, підпис, зроблений приватним ключем сертифіката, і Finished.",Chain:"Ланцюжок","Site → intermediate → root":"Сайт → проміжний → кореневий","Proves the private key":"Доводить приватний ключ",Checked:"Перевіряється","Name, dates, trusted root":"Ім’я, дати, довірений корінь","encrypted: http/1.1, certificates,":"зашифровано: http/1.1, сертифікати,","signature, Finished":"підпис, Finished","One round trip, then data":"Один обмін туди-назад, потім дані","The browser sends its own Finished: a check value over everything both sides said, keyed with the new secret, so any tampering with the hellos would show. TLS 1.3 needs one round trip before data flows; TLS 1.2 needed two.":"Браузер надсилає свій Finished: контрольне значення для всього, що сказали обидві сторони, обчислене з новим секретом, тож будь-яке втручання в привітання стало б помітним. TLS 1.3 потребує одного обміну туди-назад, перш ніж підуть дані; TLS 1.2 потребував двох.",Covers:"Охоплює","The whole handshake":"Усе рукостискання","For old middleboxes":"Для старих проміжних пристроїв","check value over":"контрольне значення для","the whole handshake":"всього рукостискання","Encrypted Data":"Зашифровані дані","Records, tags and tickets":"Записи, теги й квитки","HTTP now travels in encrypted records, each with a 16-byte tag that exposes any change. The server also sends two session tickets: next time the browser can resume with one and skip the certificate.":"HTTP тепер їде в зашифрованих записах, кожен із 16-байтовим тегом, що викриває будь-яку зміну. Сервер також надсилає два сеансові квитки: наступного разу браузер зможе відновити сеанс одним із них і пропустити сертифікат.","Per record":"На запис","22 bytes of overhead":"22 байти накладних витрат","2, for resuming later":"2, для відновлення згодом",Visible:"Що видно","IPs, SNI, sizes, timing":"IP-адреси, SNI, розміри, час","2 session tickets":"2 сеансові квитки","for resuming later":"для відновлення згодом",Closing:"Закриття","close_notify, then TCP":"close_notify, потім TCP","After 75 idle seconds the server closes the connection. It first sends a close_notify alert, encrypted like everything else, so the browser knows the data ended on purpose and wasn’t cut short by an attacker. Then TCP closes as usual.":"Після 75 секунд бездіяльності сервер закриває з’єднання. Спершу він надсилає попередження close_notify, зашифроване, як і все інше, щоб браузер знав, що дані закінчилися навмисно, а не були обірвані зловмисником. Потім TCP закривається як завжди.",Alert:"Попередження","Shows nothing was cut off":"Показує, що нічого не обірвано","TCP FIN from both sides":"TCP FIN від обох сторін","alert: close_notify":"попередження: close_notify",encrypted:"зашифровано","Server Hello, Change Cipher Spec (+ encrypted)":"Server Hello, Change Cipher Spec (+ зашифроване)","Encrypted handshake (continued)":"Зашифроване рукостискання (продовження)","Encrypted handshake (certificate, verify, Finished)":"Зашифроване рукостискання (сертифікат, перевірка, Finished)","Application Data (inside: close_notify alert)":"Application Data (усередині: попередження close_notify)","Alert: close_notify (the data ends here, on purpose)":"Alert: close_notify (дані закінчуються тут, навмисно)","No IP address":"Немає IP-адреси","192.168.1.1 · DHCP server":"192.168.1.1 · DHCP-сервер"},r=(t,e,s,o)=>{const h=Number(String(t).replace(/\D/g,"")),n=h%10,i=h%100;return n===1&&i!==11?e:n>=2&&n<=4&&(i<12||i>14)?s:o},a=t=>`${t} ${r(t,"байт","байти","байтів")}`,d=t=>`${t} ${r(t,"сегмент","сегменти","сегментів")}`,c=t=>`${t} ${r(t,"запис","записи","записів")}`,S={strings:{...T,...p},patterns:[[/^([\d,]+) bytes$/,(t,e)=>a(e)],[/^(Ethernet II|IPv4|UDP|TCP) · (\d+) bytes$/,(t,e,s)=>`${e} · ${a(s)}`],[/^(Application Data|Handshake|Change Cipher Spec), ([\d,]+) bytes?$/,(t,e,s)=>`${e}, ${a(s)}`],[/^([\d,]+) bytes: report\.pdf, bytes (.+)$/,(t,e,s)=>`${a(e)}: report.pdf, байти ${s}`],[/^(.+) h later$/,"через $1 h"],[/^(.+) min later$/,"через $1 min"],[/^(.+) s later$/,"через $1 s"],[/^(\S+) \(relative\)$/,"$1 (відносний)"],[/^(\d+) \(ephemeral\)$/,"$1 (тимчасовий)"],[/^(\d+) TCP segments$/,(t,e)=>`${e} TCP-${r(e,"сегмент","сегменти","сегментів")}`],[/^(\d+) segments$/,(t,e)=>d(e)],[/^(.*), (\d+) segments$/,(t,e,s)=>`${e}, ${d(s)}`],[/^TLS 1\.3 · (\d+) records? · bytes (.+) of (.+)$/,(t,e,s,o)=>`TLS 1.3 · ${c(e)} · байти ${s} з ${o}`],[/^TLS 1\.3 · (\d+) records?$/,(t,e)=>`TLS 1.3 · ${c(e)}`],[/^Ethernet padding · (\d+) bytes$/,(t,e)=>`Доповнення Ethernet · ${a(e)}`],[/^(\d+) zero bytes, up to the 300-byte minimum$/,(t,e)=>`${e} ${r(e,"нульовий байт","нульові байти","нульових байтів")}, до мінімуму в 300 байтів`],[/^(\d+) zero bytes$/,(t,e)=>`${e} ${r(e,"нульовий байт","нульові байти","нульових байтів")}`],[/^(\d+) random bytes$/,(t,e)=>`${e} ${r(e,"випадковий байт","випадкові байти","випадкових байтів")}`],[/^Seen as it leaves (.+)$/,"Як видно на виході з $1"],[/^Option (\d+)$/,"Опція $1"],[/^value (\d+), echo (\d+)$/,"значення $1, відлуння $2"],[/^20 bytes, plus (\d+) of options\.$/,(t,e)=>`20 байтів плюс ${a(e)} опцій.`],[/^Windows starts at (\d+)\. Set to (\d+) on purpose here\.$/,"Windows починає з $1. Тут навмисно встановлено $2."],[/^Started at (\d+); (\d+) routers? on the way each took 1\.$/,(t,e,s)=>s==="1"?`Почалося з ${e}; маршрутизатор на шляху відняв 1.`:`Почалося з ${e}; кожен із ${s} маршрутизаторів на шляху відняв 1.`],[/^all (\d+) bytes of it$/,(t,e)=>`усі ${a(e)}`],[/^The packet that caused this, as the reporting device received it \(TTL (\d+)\), so the sender can tell which packet it was\.$/,"Пакет, що спричинив це, у тому вигляді, в якому його отримав пристрій, що звітує (TTL $1), щоб відправник зрозумів, про який пакет ідеться."],[/^Port (\d+), TLS from the start$/,"Порт $1, TLS від самого початку"],[/^(\d+), TLS from the start$/,"$1, TLS від самого початку"]],post:l};export{S as default};
